pub(crate) const INVOCATION_COST_AUDIT_REASON_RECORDED_COST_MISSING: &str = "recorded_cost_missing";
pub(crate) const INVOCATION_COST_AUDIT_REASON_RECORDED_PRICE_VERSION_MISSING: &str =
    "recorded_price_version_missing";
pub(crate) const INVOCATION_COST_AUDIT_REASON_PRICING_MODE_UNKNOWN: &str = "pricing_mode_unknown";
pub(crate) const INVOCATION_COST_AUDIT_REASON_USAGE_MISSING: &str = "usage_missing";
pub(crate) const INVOCATION_COST_AUDIT_REASON_MODEL_MISSING: &str = "model_missing";
pub(crate) const INVOCATION_COST_AUDIT_REASON_MODEL_PRICING_MISSING: &str = "model_pricing_missing";
pub(crate) const INVOCATION_COST_AUDIT_REASON_PRICE_VERSION_CHANGED: &str = "price_version_changed";
pub(crate) const INVOCATION_COST_AUDIT_REASON_TOTAL_MISMATCH: &str = "total_mismatch";

fn resolve_invocation_cache_write_tokens(record: &ApiInvocation) -> Option<i64> {
    record.cache_write_tokens.or_else(|| {
        record
            .input_tokens
            .map(|input| input.saturating_sub(record.cache_input_tokens.unwrap_or_default().max(0)))
    })
}

fn invocation_has_usage_evidence(record: &ApiInvocation) -> bool {
    [
        record.input_tokens,
        record.output_tokens,
        record.cache_input_tokens,
        record.reasoning_tokens,
        record.total_tokens,
        resolve_invocation_cache_write_tokens(record),
    ]
    .into_iter()
    .any(|value| value.is_some())
        || record.cost.is_some()
        || record.cost_input.is_some()
        || record.cost_cache_write.is_some()
        || record.cost_cache_read.is_some()
        || record.cost_output.is_some()
        || record.cost_reasoning.is_some()
}

fn invocation_usage_for_cost_audit(record: &ApiInvocation) -> ParsedUsage {
    ParsedUsage {
        input_tokens: record.input_tokens,
        output_tokens: record.output_tokens,
        cache_input_tokens: record.cache_input_tokens,
        reasoning_tokens: record.reasoning_tokens,
        total_tokens: record.total_tokens,
    }
}

fn invocation_billable_model(record: &ApiInvocation) -> Option<&str> {
    record
        .response_model
        .as_deref()
        .or(record.model.as_deref())
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

fn resolve_invocation_pricing_mode(
    price_version: Option<&str>,
) -> Result<ProxyPricingMode, &'static str> {
    let normalized = price_version
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or(INVOCATION_COST_AUDIT_REASON_RECORDED_PRICE_VERSION_MISSING)?;
    if normalized.ends_with(REQUESTED_TIER_PRICE_VERSION_SUFFIX) {
        return Ok(ProxyPricingMode::RequestedTier);
    }
    if normalized.ends_with(RESPONSE_TIER_PRICE_VERSION_SUFFIX) {
        return Ok(ProxyPricingMode::ResponseTier);
    }
    if normalized.ends_with(EXPLICIT_BILLING_PRICE_VERSION_SUFFIX) {
        return Ok(ProxyPricingMode::ExplicitBilling);
    }
    Err(INVOCATION_COST_AUDIT_REASON_PRICING_MODE_UNKNOWN)
}

fn build_invocation_cost_audit_breakdown(
    total: Option<f64>,
    input: Option<f64>,
    cache_write: Option<f64>,
    cache_read: Option<f64>,
    output: Option<f64>,
    reasoning: Option<f64>,
    include_breakdown: bool,
) -> Option<InvocationCostAuditBreakdown> {
    let has_components = [input, cache_write, cache_read, output, reasoning]
        .into_iter()
        .any(|value| value.is_some());
    if total.is_none() && !(include_breakdown && has_components) {
        return None;
    }
    Some(InvocationCostAuditBreakdown {
        input: include_breakdown.then_some(input).flatten(),
        cache_write: include_breakdown.then_some(cache_write).flatten(),
        cache_read: include_breakdown.then_some(cache_read).flatten(),
        output: include_breakdown.then_some(output).flatten(),
        reasoning: include_breakdown.then_some(reasoning).flatten(),
        total,
    })
}

fn build_recorded_invocation_cost_breakdown(
    record: &ApiInvocation,
    include_breakdown: bool,
) -> Option<InvocationCostAuditBreakdown> {
    build_invocation_cost_audit_breakdown(
        record.cost,
        record.cost_input,
        record.cost_cache_write,
        record.cost_cache_read,
        record.cost_output,
        record.cost_reasoning,
        include_breakdown,
    )
}

fn build_local_invocation_cost_breakdown(
    record: &ApiInvocation,
    catalog: &PricingCatalog,
    include_breakdown: bool,
) -> (
    Option<InvocationCostAuditBreakdown>,
    Option<String>,
    Option<&'static str>,
) {
    let pricing_mode = match resolve_invocation_pricing_mode(record.price_version.as_deref()) {
        Ok(mode) => mode,
        Err(reason) => return (None, None, Some(reason)),
    };
    let local_price_version = Some(proxy_price_version(&catalog.version, pricing_mode));
    let usage = invocation_usage_for_cost_audit(record);
    if !has_billable_usage(&usage) {
        return (
            None,
            local_price_version,
            Some(INVOCATION_COST_AUDIT_REASON_USAGE_MISSING),
        );
    }
    let Some(model) = invocation_billable_model(record) else {
        return (
            None,
            local_price_version,
            Some(INVOCATION_COST_AUDIT_REASON_MODEL_MISSING),
        );
    };
    let (breakdown, _, _) = estimate_proxy_cost_breakdown(
        catalog,
        Some(model),
        &usage,
        record.billing_service_tier.as_deref(),
        pricing_mode,
    );
    let Some(breakdown) = breakdown else {
        return (
            None,
            local_price_version,
            Some(INVOCATION_COST_AUDIT_REASON_MODEL_PRICING_MISSING),
        );
    };
    (
        build_invocation_cost_audit_breakdown(
            Some(breakdown.total()),
            Some(breakdown.input),
            Some(breakdown.cache_write),
            Some(breakdown.cache_read),
            Some(breakdown.output),
            Some(breakdown.reasoning),
            include_breakdown,
        ),
        local_price_version,
        None,
    )
}

fn build_invocation_cost_audit(
    record: &ApiInvocation,
    catalog: &PricingCatalog,
    include_breakdown: bool,
) -> Option<InvocationCostAudit> {
    let recorded = build_recorded_invocation_cost_breakdown(record, include_breakdown);
    let recorded_total = recorded.as_ref().and_then(|value| value.total);
    let (local, local_price_version, unavailable_reason) =
        build_local_invocation_cost_breakdown(record, catalog, include_breakdown);
    let local_total = local.as_ref().and_then(|value| value.total);
    let absolute_diff_usd = match (recorded_total, local_total) {
        (Some(recorded_total), Some(local_total)) => Some((recorded_total - local_total).abs()),
        _ => None,
    };
    let mismatch =
        absolute_diff_usd.is_some_and(|diff| diff > INVOCATION_COST_AUDIT_MISMATCH_EPSILON_USD);
    let recorded_price_version = normalize_query_text(record.price_version.as_deref());
    let reason = if mismatch {
        if recorded_price_version.as_deref() != local_price_version.as_deref() {
            Some(INVOCATION_COST_AUDIT_REASON_PRICE_VERSION_CHANGED.to_string())
        } else {
            Some(INVOCATION_COST_AUDIT_REASON_TOTAL_MISMATCH.to_string())
        }
    } else if recorded_total.is_none() && local_total.is_some() {
        Some(INVOCATION_COST_AUDIT_REASON_RECORDED_COST_MISSING.to_string())
    } else if recorded_total.is_some() && local_total.is_none() {
        unavailable_reason.map(str::to_string)
    } else {
        None
    };
    if recorded.is_none()
        && local.is_none()
        && recorded_price_version.is_none()
        && local_price_version.is_none()
        && reason.is_none()
    {
        return None;
    }
    Some(InvocationCostAudit {
        recorded,
        local,
        mismatch,
        reason,
        absolute_diff_usd,
        recorded_price_version,
        local_price_version,
    })
}

fn apply_invocation_cost_audits(records: &mut [ApiInvocation], catalog: &PricingCatalog) {
    for record in records {
        record.cost_audit = build_invocation_cost_audit(record, catalog, false);
    }
}

fn build_invocation_usage_summary(
    record: &ApiInvocation,
    cost_audit: &InvocationCostAudit,
) -> Value {
    let recorded = cost_audit
        .recorded
        .as_ref()
        .map(|breakdown| json!(breakdown));
    let local = cost_audit.local.as_ref().map(|breakdown| json!(breakdown));
    json!({
        "inputTokens": record.input_tokens,
        "cacheWriteTokens": resolve_invocation_cache_write_tokens(record),
        "cacheInputTokens": record.cache_input_tokens,
        "outputTokens": record.output_tokens,
        "reasoningTokens": record.reasoning_tokens,
        "totalTokens": record.total_tokens,
        "cost": record.cost,
        "tokens": {
            "input": record.input_tokens,
            "cacheWrite": resolve_invocation_cache_write_tokens(record),
            "cacheRead": record.cache_input_tokens,
            "output": record.output_tokens,
            "reasoning": record.reasoning_tokens,
            "total": record.total_tokens,
        },
        "costs": {
            "recorded": recorded,
            "local": local,
        },
        "audit": cost_audit,
    })
}

fn build_workflow_hero(
    record: &ApiInvocation,
    payload: Option<&Value>,
    timeline_attempt_count: usize,
) -> InvocationWorkflowHero {
    InvocationWorkflowHero {
        record_id: record.id,
        invoke_id: record.invoke_id.clone(),
        prompt_cache_key: record.prompt_cache_key.clone(),
        route_mode: record.route_mode.clone(),
        endpoint: record.endpoint.clone(),
        request_model: record.request_model.clone(),
        response_model: record
            .response_model
            .clone()
            .or_else(|| record.model.clone()),
        final_status: record.status.clone(),
        failure_class: record.failure_class.clone(),
        downstream_status_code: record.downstream_status_code,
        upstream_account_id: record.upstream_account_id,
        upstream_account_name: record.upstream_account_name.clone(),
        total_duration_ms: record.t_total_ms,
        timeline_attempt_count,
        pool_attempt_count: record.pool_attempt_count,
        total_tokens: record.total_tokens,
        cost: record.cost,
        occurred_at: Some(record.occurred_at.clone()),
        pool_routing_no_candidate_audit: payload_clone(payload, &["poolRoutingNoCandidateAudit"])
            .and_then(|value| serde_json::from_value(value).ok()),
    }
}

fn build_attempt_request_summary(
    record: &ApiInvocation,
    attempt: &InvocationWorkflowAttemptRow,
    payload: Option<&Value>,
) -> Value {
    let compression = request_compression_value(
        attempt.upstream_request_compression_algorithm.clone(),
        attempt.upstream_request_compression_mode.clone(),
        derive_request_compression_fields(
            attempt.upstream_request_logical_body_bytes,
            attempt.upstream_request_transmitted_body_bytes,
            attempt.upstream_request_header_bytes_approx,
            attempt.upstream_response_body_bytes,
            attempt.upstream_response_header_bytes_approx,
            attempt.http_status.is_some()
                || attempt
                    .status
                    .eq_ignore_ascii_case(POOL_UPSTREAM_REQUEST_ATTEMPT_STATUS_SUCCESS),
        ),
    );
    let image_tool_rewrite = payload_clone(payload, &["imageToolRewrite"]);
    let codex_imagegen_rewrite = payload_clone(payload, &["codexImagegenRewrite"]);
    let mut summary = json!({
        "endpoint": attempt.endpoint.clone(),
        "routeMode": record.route_mode.clone(),
        "transport": record.transport.clone(),
        "requestModel": record.request_model.clone(),
        "responseModel": record.response_model.as_ref().or(record.model.as_ref()),
        "requestedServiceTier": record.requested_service_tier.clone(),
        "reasoningEffort": record.reasoning_effort.clone(),
        "compactionRequestKind": record.compaction_request_kind.clone(),
        "imageIntent": record.image_intent.clone(),
        "promptCacheKey": record.prompt_cache_key.clone(),
        "stickyKey": attempt.sticky_key.as_ref().or(record.sticky_key.as_ref()),
        "requesterIp": attempt.requester_ip.as_ref().or(record.requester_ip.as_ref()),
        "account": {
            "id": attempt.upstream_account_id,
            "name": attempt.upstream_account_name.as_ref().or(record.upstream_account_name.as_ref()),
        },
        "routing": {
            "upstreamRouteKey": attempt.upstream_route_key.clone(),
            "proxyBindingKey": attempt.proxy_binding_key_snapshot.clone(),
            "proxyDisplayName": record.proxy_display_name.clone(),
            "upstreamScope": payload_string(payload, &["upstreamScope"]),
            "clientFingerprint": payload_string(payload, &["clientFingerprint"]),
            "oauthForwardedHeaderNames": payload_string_array(payload, &["oauthForwardedHeaderNames"]),
            "oauthPromptCacheHeaderForwarded": payload_bool(payload, &["oauthPromptCacheHeaderForwarded"]),
        },
        "headers": build_request_header_snapshot(payload),
        "client": build_request_client_snapshot(payload),
        "compression": compression,
        "bodyCapture": {
            "availableAtInvocationLevel": record.request_raw_path.is_some(),
            "size": record.request_raw_size,
            "truncated": record.request_raw_truncated.unwrap_or_default() != 0,
            "truncatedReason": record.request_raw_truncated_reason.clone(),
            "detailLevel": record.detail_level.clone(),
            "detailPruneReason": record.detail_prune_reason.clone(),
        },
    });
    if let Some(image_tool_rewrite) = image_tool_rewrite {
        summary["imageToolRewrite"] = image_tool_rewrite;
    }
    if let Some(codex_imagegen_rewrite) = codex_imagegen_rewrite {
        summary["codexImagegenRewrite"] = codex_imagegen_rewrite;
    }
    summary
}

fn build_attempt_response_summary(
    record: &ApiInvocation,
    attempt: &InvocationWorkflowAttemptRow,
    payload: Option<&Value>,
    usage_cost_audit: Option<&InvocationCostAudit>,
    is_final_attempt: bool,
) -> Value {
    let invocation_failure_kind = is_final_attempt
        .then_some(record.failure_kind.as_ref())
        .flatten();
    let invocation_error_message = is_final_attempt
        .then_some(record.error_message.as_ref())
        .flatten();
    let invocation_downstream_error_message = is_final_attempt
        .then_some(record.downstream_error_message.as_ref())
        .flatten();
    let invocation_upstream_request_id = is_final_attempt
        .then_some(record.upstream_request_id.as_ref())
        .flatten();
    let invocation_response_content_encoding =
        attempt.response_content_encoding.clone().or_else(|| {
            is_final_attempt
                .then(|| record.response_content_encoding.clone())
                .flatten()
        });
    let invocation_response_payload = is_final_attempt.then_some(payload).flatten();
    let attempt_response_body_captured = attempt.response_raw_path.is_some();
    let response_body_capture_size = attempt
        .response_raw_size
        .or_else(|| {
            is_final_attempt
                .then_some(record.response_raw_size)
                .flatten()
        })
        .or(attempt.upstream_response_body_bytes);
    let response_body_capture_truncated = if attempt_response_body_captured {
        attempt.response_raw_truncated.unwrap_or_default() != 0
    } else if is_final_attempt && record.response_raw_path.is_some() {
        record.response_raw_truncated.unwrap_or_default() != 0
    } else {
        false
    };
    let response_body_capture_truncated_reason =
        attempt.response_raw_truncated_reason.clone().or_else(|| {
            is_final_attempt
                .then(|| record.response_raw_truncated_reason.clone())
                .flatten()
        });
    let response_body_capture_detail_level = if attempt_response_body_captured {
        Some(record.detail_level.clone())
    } else if is_final_attempt && record.response_raw_path.is_some() {
        Some("full".to_string())
    } else {
        Some("attempt_metrics".to_string())
    };

    json!({
        "status": attempt.status.clone(),
        "phase": attempt.phase.clone(),
        "httpStatus": attempt.http_status,
        "compactionResponseKind": is_final_attempt.then(|| record.compaction_response_kind.clone()).flatten(),
        "failureKind": attempt.failure_kind.as_ref().or(invocation_failure_kind),
        "errorMessage": attempt.error_message.as_ref().or(invocation_error_message),
        "downstreamErrorMessage": attempt
            .downstream_error_message
            .as_ref()
            .or(invocation_downstream_error_message),
        "upstreamRequestId": attempt.upstream_request_id.as_ref().or(invocation_upstream_request_id),
        "upstreamErrorCode": is_final_attempt.then(|| record.upstream_error_code.clone()).flatten(),
        "upstreamErrorMessage": is_final_attempt.then(|| record.upstream_error_message.clone()).flatten(),
        "streamTerminalEvent": is_final_attempt.then(|| record.stream_terminal_event.clone()).flatten(),
        "responseContentEncoding": invocation_response_content_encoding,
        "serviceTier": is_final_attempt.then(|| record.service_tier.clone()).flatten(),
        "billingServiceTier": is_final_attempt.then(|| record.billing_service_tier.clone()).flatten(),
        "headers": build_response_header_snapshot(record, Some(attempt), payload, is_final_attempt),
        "delivery": build_response_delivery_snapshot(invocation_response_payload),
        "compactSupport": {
            "status": attempt.compact_support_status.clone(),
            "reason": attempt.compact_support_reason.clone(),
        },
        "latencyMs": {
            "connect": finite_nonnegative_timing(attempt.connect_latency_ms.or_else(|| is_final_attempt.then_some(record.t_upstream_connect_ms).flatten())),
            "firstByte": finite_nonnegative_timing(attempt.first_byte_latency_ms.or_else(|| is_final_attempt.then_some(record.t_upstream_ttfb_ms).flatten())),
            "stream": if is_final_attempt {
                final_attempt_has_stream_evidence(attempt)
                    .then_some(finite_positive_timing(attempt.stream_latency_ms))
                    .flatten()
            } else {
                finite_positive_timing(attempt.stream_latency_ms)
            },
            "requestRead": is_final_attempt.then_some(finite_nonnegative_timing(record.t_req_read_ms)).flatten(),
            "requestParse": is_final_attempt.then_some(finite_nonnegative_timing(record.t_req_parse_ms)).flatten(),
            "responseParse": is_final_attempt.then_some(finite_nonnegative_timing(record.t_resp_parse_ms)).flatten(),
            "persist": is_final_attempt.then_some(finite_nonnegative_timing(record.t_persist_ms)).flatten(),
            "total": is_final_attempt.then_some(finite_nonnegative_timing(record.t_total_ms)).flatten(),
        },
        "responseBodyCapture": {
            "availableAtAttemptLevel": attempt_response_body_captured,
            "availableAtInvocationLevel": is_final_attempt && record.response_raw_path.is_some(),
            "size": response_body_capture_size,
            "truncated": response_body_capture_truncated,
            "truncatedReason": response_body_capture_truncated_reason,
            "detailLevel": response_body_capture_detail_level,
            "detailPruneReason": is_final_attempt.then(|| record.detail_prune_reason.clone()).flatten(),
            "unavailableReason": (!(attempt_response_body_captured || (is_final_attempt && record.response_raw_path.is_some())))
                .then_some("attempt_response_body_not_captured"),
        },
        "usage": usage_cost_audit.map(|audit| build_invocation_usage_summary(record, audit)),
    })
}

fn build_workflow_attempt_from_row(
    record: &ApiInvocation,
    attempt: &InvocationWorkflowAttemptRow,
    payload: Option<&Value>,
    usage_cost_audit: Option<&InvocationCostAudit>,
    is_final_attempt: bool,
) -> InvocationWorkflowAttempt {
    let invocation_failure_kind = is_final_attempt
        .then(|| record.failure_kind.clone())
        .flatten();
    let invocation_error_message = is_final_attempt
        .then(|| record.error_message.clone())
        .flatten();
    let invocation_downstream_error_message = is_final_attempt
        .then(|| record.downstream_error_message.clone())
        .flatten();
    let invocation_upstream_request_id = is_final_attempt
        .then(|| record.upstream_request_id.clone())
        .flatten();

    InvocationWorkflowAttempt {
        synthetic: false,
        attempt_id: attempt.attempt_id.clone(),
        occurred_at: attempt.occurred_at.clone(),
        endpoint: attempt.endpoint.clone(),
        sticky_key: attempt.sticky_key.clone(),
        routing_source: attempt.routing_source.clone(),
        routing_selection_audit: attempt
            .routing_selection_audit_json
            .as_deref()
            .and_then(|value| serde_json::from_str(value).ok()),
        upstream_account_id: attempt.upstream_account_id,
        upstream_account_name: attempt.upstream_account_name.clone(),
        request_model: record.request_model.clone(),
        response_model: record
            .response_model
            .clone()
            .or_else(|| record.model.clone()),
        upstream_route_key: attempt.upstream_route_key.clone(),
        proxy_binding_key_snapshot: attempt.proxy_binding_key_snapshot.clone(),
        attempt_index: attempt.attempt_index,
        distinct_account_index: attempt.distinct_account_index,
        same_account_retry_index: attempt.same_account_retry_index,
        requester_ip: attempt
            .requester_ip
            .clone()
            .or_else(|| record.requester_ip.clone()),
        started_at: normalize_optional_timestamp(attempt.started_at.as_deref()),
        finished_at: normalize_optional_timestamp(attempt.finished_at.as_deref()),
        status: attempt.status.clone(),
        phase: attempt.phase.clone(),
        http_status: attempt.http_status,
        downstream_http_status: attempt.downstream_http_status,
        failure_kind: attempt.failure_kind.clone().or(invocation_failure_kind),
        error_message: attempt.error_message.clone().or(invocation_error_message),
        downstream_error_message: attempt
            .downstream_error_message
            .clone()
            .or(invocation_downstream_error_message),
        connect_latency_ms: finite_nonnegative_timing(attempt.connect_latency_ms.or_else(|| {
            is_final_attempt
                .then_some(record.t_upstream_connect_ms)
                .flatten()
        })),
        first_token_ms: is_final_attempt
            .then(|| {
                final_attempt_has_first_token_evidence(record, attempt)
                    .then_some(finite_nonnegative_timing(record.first_token_ms))
                    .flatten()
            })
            .flatten(),
        first_byte_latency_ms: finite_nonnegative_timing(attempt.first_byte_latency_ms.or_else(
            || {
                is_final_attempt
                    .then_some(record.t_upstream_ttfb_ms)
                    .flatten()
            },
        )),
        stream_latency_ms: if is_final_attempt {
            final_attempt_has_stream_evidence(attempt)
                .then_some(finite_positive_timing(attempt.stream_latency_ms))
                .flatten()
        } else {
            finite_positive_timing(attempt.stream_latency_ms)
        },
        upstream_request_id: attempt
            .upstream_request_id
            .clone()
            .or(invocation_upstream_request_id),
        request_summary: merge_attempt_request_summary_json(
            attempt.request_summary_json.as_deref(),
            build_attempt_request_summary(record, attempt, payload),
        ),
        response_summary: parse_summary_json_or_fallback(
            attempt.response_summary_json.as_deref(),
            || {
                build_attempt_response_summary(
                    record,
                    attempt,
                    payload,
                    usage_cost_audit,
                    is_final_attempt,
                )
            },
        )
        .map(|summary| sanitize_response_summary_timing(summary, attempt, is_final_attempt)),
    }
}

fn build_synthetic_workflow_attempt(
    record: &ApiInvocation,
    payload: Option<&Value>,
    usage_cost_audit: Option<&InvocationCostAudit>,
) -> InvocationWorkflowAttempt {
    let request_compression = request_compression_value(
        payload_string(payload, &["requestCompressionAlgorithm"]),
        payload_string(payload, &["requestCompressionMode"]),
        derive_request_compression_from_payload(payload),
    );
    let request_summary = json!({
        "endpoint": record.endpoint.clone(),
        "routeMode": record.route_mode.clone(),
        "transport": record.transport.clone(),
        "requestModel": record.request_model.clone(),
        "responseModel": record.response_model.as_ref().or(record.model.as_ref()),
        "requestedServiceTier": record.requested_service_tier.clone(),
        "reasoningEffort": record.reasoning_effort.clone(),
        "compactionRequestKind": record.compaction_request_kind.clone(),
        "imageIntent": record.image_intent.clone(),
        "promptCacheKey": record.prompt_cache_key.clone(),
        "stickyKey": record.sticky_key.clone(),
        "requesterIp": record.requester_ip.clone(),
        "account": {
            "id": record.upstream_account_id,
            "name": record.upstream_account_name.clone(),
        },
        "routing": {
            "proxyDisplayName": record.proxy_display_name.clone(),
            "upstreamScope": payload_string(payload, &["upstreamScope"]),
            "clientFingerprint": payload_string(payload, &["clientFingerprint"]),
            "oauthForwardedHeaderNames": payload_string_array(payload, &["oauthForwardedHeaderNames"]),
            "oauthPromptCacheHeaderForwarded": payload_bool(payload, &["oauthPromptCacheHeaderForwarded"]),
        },
        "headers": build_request_header_snapshot(payload),
        "client": build_request_client_snapshot(payload),
        "compression": request_compression,
        "bodyCapture": {
            "availableAtInvocationLevel": record.request_raw_path.is_some(),
            "size": record.request_raw_size,
            "truncated": record.request_raw_truncated.unwrap_or_default() != 0,
            "truncatedReason": record.request_raw_truncated_reason.clone(),
            "detailLevel": record.detail_level.clone(),
            "detailPruneReason": record.detail_prune_reason.clone(),
        },
    });
    let response_summary = json!({
        "status": record.status.clone(),
        "phase": record.live_phase.clone(),
        "downstreamHttpStatus": record.downstream_status_code,
        "failureKind": record.failure_kind.clone(),
        "errorMessage": record.error_message.clone(),
        "downstreamErrorMessage": record.downstream_error_message.clone(),
        "upstreamRequestId": record.upstream_request_id.clone(),
        "upstreamErrorCode": record.upstream_error_code.clone(),
        "upstreamErrorMessage": record.upstream_error_message.clone(),
        "streamTerminalEvent": record.stream_terminal_event.clone(),
        "responseContentEncoding": record.response_content_encoding.clone(),
        "serviceTier": record.service_tier.clone(),
        "billingServiceTier": record.billing_service_tier.clone(),
        "headers": build_response_header_snapshot(record, None, payload, true),
        "delivery": build_response_delivery_snapshot(payload),
        "latencyMs": {
            "connect": finite_nonnegative_timing(record.t_upstream_connect_ms),
            "firstByte": finite_nonnegative_timing(record.t_upstream_ttfb_ms),
            "stream": finite_positive_timing(record.t_upstream_stream_ms),
            "requestRead": finite_nonnegative_timing(record.t_req_read_ms),
            "requestParse": finite_nonnegative_timing(record.t_req_parse_ms),
            "responseParse": finite_nonnegative_timing(record.t_resp_parse_ms),
            "persist": finite_nonnegative_timing(record.t_persist_ms),
            "total": finite_nonnegative_timing(record.t_total_ms),
        },
        "responseBodyCapture": {
            "availableAtInvocationLevel": record.response_raw_path.is_some(),
            "size": record.response_raw_size,
            "truncated": record.response_raw_truncated.unwrap_or_default() != 0,
            "truncatedReason": record.response_raw_truncated_reason.clone(),
            "detailLevel": record.detail_level.clone(),
            "detailPruneReason": record.detail_prune_reason.clone(),
        },
        "usage": usage_cost_audit.map(|audit| build_invocation_usage_summary(record, audit)),
    });
    InvocationWorkflowAttempt {
        synthetic: true,
        attempt_id: None,
        occurred_at: record.occurred_at.clone(),
        endpoint: record.endpoint.clone().unwrap_or_default(),
        sticky_key: record.sticky_key.clone(),
        routing_source: None,
        routing_selection_audit: None,
        upstream_account_id: record.upstream_account_id,
        upstream_account_name: record.upstream_account_name.clone(),
        request_model: record.request_model.clone(),
        response_model: record
            .response_model
            .clone()
            .or_else(|| record.model.clone()),
        upstream_route_key: None,
        proxy_binding_key_snapshot: None,
        attempt_index: 1,
        distinct_account_index: 1,
        same_account_retry_index: 1,
        requester_ip: record.requester_ip.clone(),
        started_at: Some(record.occurred_at.clone()),
        finished_at: record.t_total_ms.and_then(|total| {
            parse_to_utc_datetime(&record.occurred_at).and_then(|occurred_at| {
                chrono::Duration::from_std(Duration::from_secs_f64(total.max(0.0) / 1000.0))
                    .ok()
                    .map(|delta| format_utc_iso(occurred_at + delta))
            })
        }),
        status: record
            .status
            .clone()
            .unwrap_or_else(|| "unknown".to_string()),
        phase: record.live_phase.clone(),
        http_status: None,
        downstream_http_status: record.downstream_status_code,
        failure_kind: record.failure_kind.clone(),
        error_message: record.error_message.clone(),
        downstream_error_message: record.downstream_error_message.clone(),
        connect_latency_ms: finite_nonnegative_timing(record.t_upstream_connect_ms),
        first_token_ms: finite_nonnegative_timing(record.first_token_ms),
        first_byte_latency_ms: finite_nonnegative_timing(record.t_upstream_ttfb_ms),
        stream_latency_ms: finite_positive_timing(record.t_upstream_stream_ms),
        upstream_request_id: record.upstream_request_id.clone(),
        request_summary: Some(request_summary),
        response_summary: Some(response_summary),
    }
}

fn workflow_attempt_account_label(attempt: &InvocationWorkflowAttempt) -> String {
    attempt
        .upstream_account_name
        .clone()
        .or_else(|| attempt.upstream_account_id.map(|id| format!("账号 #{id}")))
        .unwrap_or_else(|| "未定账号".to_string())
}

fn workflow_route_subtitle(attempt: &InvocationWorkflowAttempt) -> Option<String> {
    let mut parts = Vec::new();
    if let Some(model) = attempt
        .request_model
        .as_deref()
        .filter(|value| !value.trim().is_empty())
    {
        parts.push(model.to_string());
    }
    if let Some(proxy) = attempt
        .proxy_binding_key_snapshot
        .as_deref()
        .filter(|value| !value.trim().is_empty())
    {
        parts.push(proxy.to_string());
    }
    if let Some(route_key) = attempt
        .upstream_route_key
        .as_deref()
        .filter(|value| !value.trim().is_empty())
    {
        parts.push(route_key.to_string());
    }
    if parts.is_empty() {
        None
    } else {
        Some(parts.join(" · "))
    }
}

fn workflow_route_title(attempt: &InvocationWorkflowAttempt) -> String {
    let account_label = workflow_attempt_account_label(attempt);
    if account_label == "未定账号" {
        "Route resolution".to_string()
    } else {
        format!("Route {account_label}")
    }
}

fn build_routing_detail(request_summary: Option<&Value>) -> Option<Value> {
    let request = request_summary?.clone();
    let request_headers = request
        .as_object()
        .and_then(|value| value.get("headers"))
        .cloned();
    let request_body = request
        .as_object()
        .and_then(|value| value.get("bodyCapture"))
        .cloned();
    Some(json!({
        "request": request,
        "requestHeaders": request_headers,
        "requestBody": request_body,
    }))
}

fn build_routing_timeline_entry(
    block_id: String,
    attempt: &InvocationWorkflowAttempt,
) -> InvocationWorkflowTimelineEntry {
    InvocationWorkflowTimelineEntry {
        block_id,
        kind: "routingDecision".to_string(),
        occurred_at: attempt
            .started_at
            .clone()
            .or_else(|| Some(attempt.occurred_at.clone())),
        title: workflow_route_title(attempt),
        subtitle: workflow_route_subtitle(attempt)
            .or_else(|| (!attempt.endpoint.trim().is_empty()).then(|| attempt.endpoint.clone())),
        status: None,
        attempt: None,
        detail: build_routing_detail(attempt.request_summary.as_ref()),
        response_body: None,
    }
}

fn invocation_workflow_attempt_row_is_pseudo_terminal(
    attempt: &InvocationWorkflowAttemptRow,
) -> bool {
    normalized_runtime_text(Some(attempt.status.as_str())) == "budget_exhausted_final"
        && attempt.same_account_retry_index == 0
        && normalize_optional_timestamp(attempt.started_at.as_deref())
            == normalize_optional_timestamp(attempt.finished_at.as_deref())
        && attempt
            .connect_latency_ms
            .is_none_or(|value| !value.is_finite() || value <= 0.0)
        && attempt
            .first_byte_latency_ms
            .is_none_or(|value| !value.is_finite() || value <= 0.0)
        && attempt
            .stream_latency_ms
            .is_none_or(|value| !value.is_finite() || value <= 0.0)
        && attempt
            .upstream_request_id
            .as_deref()
            .map(str::trim)
            .is_none_or(str::is_empty)
        && attempt
            .request_summary_json
            .as_deref()
            .map(str::trim)
            .is_none_or(str::is_empty)
        && attempt
            .response_summary_json
            .as_deref()
            .map(str::trim)
            .is_none_or(str::is_empty)
}

fn last_success_like_attempt_row_id(attempt_rows: &[&InvocationWorkflowAttemptRow]) -> Option<i64> {
    attempt_rows
        .iter()
        .filter(|attempt| {
            matches!(
                normalized_runtime_text(Some(attempt.status.as_str())).as_str(),
                "success" | "completed" | "warning_success"
            )
        })
        .max_by_key(|attempt| (attempt.attempt_index, attempt.attempt_row_id))
        .map(|attempt| attempt.attempt_row_id)
}

fn final_real_attempt_row_id(attempts: &[&InvocationWorkflowAttemptRow]) -> Option<i64> {
    attempts
        .iter()
        .filter(|attempt| {
            normalized_runtime_text(Some(attempt.status.as_str())) != "budget_exhausted_final"
        })
        .max_by_key(|attempt| (attempt.attempt_index, attempt.attempt_row_id))
        .map(|attempt| attempt.attempt_row_id)
}

fn build_workflow_timeline_entries(
    record: &ApiInvocation,
    attempts: &[InvocationWorkflowAttempt],
    route_only_attempt: Option<&InvocationWorkflowAttempt>,
    failure_entry: Option<InvocationWorkflowTimelineEntry>,
) -> Vec<InvocationWorkflowTimelineEntry> {
    let mut entries = Vec::new();
    if let Some(route_only_attempt) = route_only_attempt {
        entries.push(build_routing_timeline_entry(
            route_only_attempt
                .attempt_id
                .clone()
                .map(|attempt_id| format!("route-{attempt_id}"))
                .unwrap_or_else(|| "route-terminal".to_string()),
            route_only_attempt,
        ));
    } else if attempts.len() == 1 && attempts[0].synthetic {
        let attempt = attempts[0].clone();
        entries.push(InvocationWorkflowTimelineEntry {
            block_id: "attempt-direct".to_string(),
            kind: "attempt".to_string(),
            occurred_at: Some(attempt.occurred_at.clone()),
            title: "Direct attempt".to_string(),
            subtitle: Some(attempt.endpoint.clone()),
            status: Some(attempt.status.clone()),
            attempt: Some(attempt),
            detail: None,
            response_body: None,
        });
    } else {
        let mut previous_finished_at: Option<DateTime<Utc>> = None;
        let mut previous_attempt_id: Option<String> = None;
        for attempt in attempts {
            if let Some(started_at) = attempt
                .started_at
                .as_deref()
                .and_then(parse_to_utc_datetime)
                && let Some(previous_finished) = previous_finished_at
            {
                let gap_ms = (started_at - previous_finished).num_milliseconds();
                if gap_ms > 0 {
                    entries.push(InvocationWorkflowTimelineEntry {
                        block_id: format!(
                            "wait-{}",
                            attempt
                                .attempt_id
                                .clone()
                                .unwrap_or_else(|| attempt.attempt_index.to_string())
                        ),
                        kind: "routingWait".to_string(),
                        occurred_at: Some(format_utc_iso(started_at)),
                        title: "Retry wait".to_string(),
                        subtitle: Some(format!("{} ms", gap_ms)),
                        status: None,
                        attempt: None,
                        detail: Some(json!({
                            "durationMs": gap_ms,
                            "fromAttemptId": previous_attempt_id.clone(),
                            "toAttemptId": attempt.attempt_id.clone(),
                        })),
                        response_body: None,
                    });
                }
            }

            entries.push(build_routing_timeline_entry(
                format!(
                    "route-{}",
                    attempt
                        .attempt_id
                        .clone()
                        .unwrap_or_else(|| attempt.attempt_index.to_string())
                ),
                attempt,
            ));

            entries.push(build_workflow_attempt_timeline_entry(attempt.clone()));

            previous_finished_at = attempt
                .finished_at
                .as_deref()
                .and_then(parse_to_utc_datetime);
            previous_attempt_id = attempt.attempt_id.clone();
        }
    }

    if let Some(failure_entry) = failure_entry {
        entries.push(failure_entry);
    }
    if entries.is_empty() && !invocation_status_is_success_like(record) {
        entries.push(InvocationWorkflowTimelineEntry {
            block_id: "failure-only".to_string(),
            kind: "systemFinalFailure".to_string(),
            occurred_at: Some(record.occurred_at.clone()),
            title: "Final downstream response".to_string(),
            subtitle: record.failure_kind.clone(),
            status: record.status.clone(),
            attempt: None,
            detail: Some(json!({
                "downstreamStatusCode": record.downstream_status_code,
                "failureKind": record.failure_kind.clone(),
                "errorMessage": record.error_message.clone(),
                "downstreamErrorMessage": record.downstream_error_message.clone(),
            })),
            response_body: None,
        });
    }
    entries
}

fn build_workflow_attempt_timeline_entry(
    attempt: InvocationWorkflowAttempt,
) -> InvocationWorkflowTimelineEntry {
    InvocationWorkflowTimelineEntry {
        block_id: format!(
            "attempt-{}",
            attempt
                .attempt_id
                .clone()
                .unwrap_or_else(|| attempt.attempt_index.to_string())
        ),
        kind: "attempt".to_string(),
        occurred_at: Some(attempt.occurred_at.clone()),
        title: format!("Attempt #{}", attempt.attempt_index),
        subtitle: Some(workflow_attempt_account_label(&attempt)),
        status: Some(attempt.status.clone()),
        attempt: Some(attempt),
        detail: None,
        response_body: None,
    }
}

pub(crate) async fn hydrate_upstream_account_attempt_workflow_entries(
    state: &AppState,
    records: &mut [ApiPoolUpstreamRequestAttempt],
) -> Result<(), ApiError> {
    if records.is_empty() {
        return Ok(());
    }

    let selectors = records
        .iter()
        .map(|record| (record.invoke_id.clone(), record.occurred_at.clone()))
        .collect::<HashSet<_>>();
    let pricing_catalog = state.pricing_catalog.read().await.clone();
    let mut hydrated = HashMap::<
        (String, String),
        Option<(
            ApiInvocation,
            HashMap<String, InvocationWorkflowTimelineEntry>,
        )>,
    >::new();

    for (invoke_id, occurred_at) in selectors {
        let record = match load_persisted_api_invocation(&state.pool, &invoke_id, &occurred_at)
            .await
        {
            Ok(record) => record,
            Err(err) => {
                debug!(
                    invoke_id,
                    occurred_at,
                    error = %err,
                    "skipping workflow hydration for account attempt without matching invocation"
                );
                hydrated.insert((invoke_id, occurred_at), None);
                continue;
            }
        };
        let body_row = fetch_invocation_response_body_row_by_id(&state.pool, record.id).await?;
        let payload_value = body_row
            .as_ref()
            .and_then(|row| parse_optional_json_value(row.payload.as_deref()));
        let attempt_rows = query_invocation_workflow_attempt_rows(
            &state.pool,
            &record.invoke_id,
            &record.occurred_at,
        )
        .await?;
        let real_attempt_rows = attempt_rows
            .iter()
            .filter(|attempt| !invocation_workflow_attempt_row_is_pseudo_terminal(attempt))
            .collect::<Vec<_>>();
        let final_attempt_row_id = final_real_attempt_row_id(&real_attempt_rows);
        let last_success_attempt_row_id = last_success_like_attempt_row_id(&real_attempt_rows);
        let usage_cost_audit = (invocation_status_is_success_like(&record)
            && invocation_has_usage_evidence(&record))
        .then(|| build_invocation_cost_audit(&record, &pricing_catalog, true))
        .flatten();
        let workflow_entries = real_attempt_rows
            .into_iter()
            .filter_map(|attempt_row| {
                let attempt = build_workflow_attempt_from_row(
                    &record,
                    attempt_row,
                    payload_value.as_ref(),
                    (last_success_attempt_row_id == Some(attempt_row.attempt_row_id))
                        .then_some(usage_cost_audit.as_ref())
                        .flatten(),
                    final_attempt_row_id == Some(attempt_row.attempt_row_id),
                );
                let attempt_id = attempt.attempt_id.clone()?;
                Some((attempt_id, build_workflow_attempt_timeline_entry(attempt)))
            })
            .collect::<HashMap<_, _>>();
        hydrated.insert(
            (record.invoke_id.clone(), record.occurred_at.clone()),
            Some((record, workflow_entries)),
        );
    }

    for item in records {
        let Some(Some((record, workflow_entries))) =
            hydrated.get(&(item.invoke_id.clone(), item.occurred_at.clone()))
        else {
            continue;
        };
        item.invocation_record = Some(record.clone());
        item.workflow_entry = workflow_entries.get(&item.attempt_id).cloned();
    }

    Ok(())
}

async fn load_invocation_workflow_identity(
    pool: &Pool<Sqlite>,
    id: i64,
) -> Result<Option<InvocationWorkflowIdentityRow>, ApiError> {
    sqlx::query_as::<_, InvocationWorkflowIdentityRow>(
        r#"
        SELECT id, invoke_id, occurred_at, timeline_json
        FROM codex_invocations
        WHERE id = ?1
        LIMIT 1
        "#,
    )
    .bind(id)
    .fetch_optional(pool)
    .await
    .map_err(ApiError::from)
}

async fn query_invocation_workflow_attempt_rows(
    pool: &Pool<Sqlite>,
    invoke_id: &str,
    occurred_at: &str,
) -> Result<Vec<InvocationWorkflowAttemptRow>, ApiError> {
    sqlx::query_as::<_, InvocationWorkflowAttemptRow>(
        r#"
        SELECT
            attempts.id AS attempt_row_id,
            attempts.attempt_public_id AS attempt_id,
            attempts.invoke_id,
            attempts.occurred_at,
            attempts.endpoint,
            attempts.sticky_key,
            attempts.routing_source,
            attempts.routing_selection_audit_json,
            attempts.upstream_account_id,
            accounts.display_name AS upstream_account_name,
            attempts.upstream_route_key,
            attempts.proxy_binding_key_snapshot,
            attempts.attempt_index,
            attempts.distinct_account_index,
            attempts.same_account_retry_index,
            attempts.requester_ip,
            attempts.started_at,
            attempts.finished_at,
            attempts.status,
            COALESCE(
                attempts.phase,
                CASE
                    WHEN attempts.status = 'pending' THEN 'sending_request'
                    WHEN attempts.status = 'success' THEN 'completed'
                    ELSE 'failed'
                END
            ) AS phase,
            attempts.http_status,
            attempts.downstream_http_status,
            attempts.failure_kind,
            attempts.error_message,
            attempts.downstream_error_message,
            attempts.connect_latency_ms,
            attempts.first_byte_latency_ms,
            attempts.stream_latency_ms,
            attempts.upstream_request_id,
            attempts.upstream_request_compression_algorithm,
            attempts.upstream_request_compression_mode,
            attempts.upstream_request_logical_body_bytes,
            attempts.upstream_request_transmitted_body_bytes,
            attempts.upstream_request_header_bytes_approx,
            attempts.upstream_response_body_bytes,
            attempts.upstream_response_header_bytes_approx,
            attempts.compact_support_status,
            attempts.compact_support_reason,
            attempts.request_summary_json,
            attempts.response_summary_json,
            attempts.response_raw_path,
            attempts.response_raw_codec,
            attempts.response_raw_size,
            attempts.response_raw_truncated,
            attempts.response_raw_truncated_reason,
            attempts.response_content_encoding
        FROM pool_upstream_request_attempts AS attempts
        LEFT JOIN pool_upstream_accounts AS accounts
            ON accounts.id = attempts.upstream_account_id
        WHERE attempts.invoke_id = ?1
          AND attempts.occurred_at = ?2
        ORDER BY attempts.attempt_index ASC, attempts.id ASC
        "#,
    )
    .bind(invoke_id)
    .bind(occurred_at)
    .fetch_all(pool)
    .await
    .map_err(ApiError::from)
}

fn build_final_failure_timeline_entry(
    record: &ApiInvocation,
    body_row: Option<&InvocationResponseBodyRow>,
    raw_path_fallback_root: Option<&Path>,
) -> Option<InvocationWorkflowTimelineEntry> {
    if invocation_status_is_success_like(record) {
        return None;
    }

    let response_body = body_row.map(|row| {
        match resolve_response_body_text_from_row(row, raw_path_fallback_root) {
            Ok((text, _)) => InvocationWorkflowResponseBody {
                available: true,
                body_text: Some(text),
                unavailable_reason: None,
            },
            Err(reason) => InvocationWorkflowResponseBody {
                available: false,
                body_text: None,
                unavailable_reason: Some(reason),
            },
        }
    });

    let occurred_at = record
        .t_total_ms
        .and_then(|total| {
            parse_to_utc_datetime(&record.occurred_at).and_then(|started_at| {
                chrono::Duration::from_std(Duration::from_secs_f64(total.max(0.0) / 1000.0))
                    .ok()
                    .map(|delta| format_utc_iso(started_at + delta))
            })
        })
        .or_else(|| Some(record.occurred_at.clone()));

    Some(InvocationWorkflowTimelineEntry {
        block_id: "system-final-failure".to_string(),
        kind: "systemFinalFailure".to_string(),
        occurred_at,
        title: "Final downstream response".to_string(),
        subtitle: record
            .failure_kind
            .clone()
            .or_else(|| record.failure_class.clone()),
        status: record.status.clone(),
        attempt: None,
        detail: Some(json!({
            "invokeId": record.invoke_id.clone(),
            "downstreamStatusCode": record.downstream_status_code,
            "failureClass": record.failure_class.clone(),
            "failureKind": record.failure_kind.clone(),
            "errorMessage": record.error_message.clone(),
            "downstreamErrorMessage": record.downstream_error_message.clone(),
            "upstreamErrorCode": record.upstream_error_code.clone(),
            "upstreamErrorMessage": record.upstream_error_message.clone(),
            "upstreamRequestId": record.upstream_request_id.clone(),
            "streamTerminalEvent": record.stream_terminal_event.clone(),
            "responseContentEncoding": record.response_content_encoding.clone(),
        })),
        response_body,
    })
}

pub(crate) async fn fetch_invocation_workflow_detail(
    State(state): State<Arc<AppState>>,
    axum::extract::Path(id): axum::extract::Path<i64>,
) -> Result<Json<InvocationWorkflowDetailResponse>, ApiError> {
    let identity = load_invocation_workflow_identity(&state.pool, id)
        .await?
        .ok_or_else(|| ApiError::bad_request(anyhow!("record not found")))?;
    let record =
        load_persisted_api_invocation(&state.pool, &identity.invoke_id, &identity.occurred_at)
            .await
            .map_err(ApiError::from)?;
    let body_row = fetch_invocation_response_body_row_by_id(&state.pool, id).await?;
    let payload_value = body_row
        .as_ref()
        .and_then(|row| parse_optional_json_value(row.payload.as_deref()));
    let attempt_rows = query_invocation_workflow_attempt_rows(
        &state.pool,
        &identity.invoke_id,
        &identity.occurred_at,
    )
    .await?;
    let pseudo_attempt_rows = attempt_rows
        .iter()
        .filter(|attempt| invocation_workflow_attempt_row_is_pseudo_terminal(attempt))
        .collect::<Vec<_>>();
    let real_attempt_rows = attempt_rows
        .iter()
        .filter(|attempt| !invocation_workflow_attempt_row_is_pseudo_terminal(attempt))
        .collect::<Vec<_>>();
    let last_success_attempt_row_id = last_success_like_attempt_row_id(&real_attempt_rows);
    let pricing_catalog = state.pricing_catalog.read().await.clone();
    let usage_cost_audit = (invocation_status_is_success_like(&record)
        && invocation_has_usage_evidence(&record))
    .then(|| build_invocation_cost_audit(&record, &pricing_catalog, true))
    .flatten();
    let pool_route = normalized_runtime_text(record.route_mode.as_deref()) == "pool";
    let render_route_only = pool_route
        && !invocation_status_is_success_like(&record)
        && real_attempt_rows.is_empty()
        && (!pseudo_attempt_rows.is_empty() || record.pool_attempt_count.unwrap_or_default() == 0);
    let route_only_attempt = render_route_only.then(|| {
        pseudo_attempt_rows
            .last()
            .map(|attempt| {
                build_workflow_attempt_from_row(
                    &record,
                    attempt,
                    payload_value.as_ref(),
                    None,
                    false,
                )
            })
            .unwrap_or_else(|| {
                build_synthetic_workflow_attempt(&record, payload_value.as_ref(), None)
            })
    });
    let attempts = if real_attempt_rows.is_empty() {
        if route_only_attempt.is_some() {
            Vec::new()
        } else {
            vec![build_synthetic_workflow_attempt(
                &record,
                payload_value.as_ref(),
                usage_cost_audit.as_ref(),
            )]
        }
    } else {
        let final_attempt_row_id = final_real_attempt_row_id(&real_attempt_rows);
        real_attempt_rows
            .iter()
            .map(|attempt| {
                build_workflow_attempt_from_row(
                    &record,
                    attempt,
                    payload_value.as_ref(),
                    (last_success_attempt_row_id == Some(attempt.attempt_row_id))
                        .then_some(usage_cost_audit.as_ref())
                        .flatten(),
                    final_attempt_row_id == Some(attempt.attempt_row_id),
                )
            })
            .collect::<Vec<_>>()
    };
    let failure_entry = build_final_failure_timeline_entry(
        &record,
        body_row.as_ref(),
        state.config.database_path.parent(),
    );
    let partial = pool_route
        && record.pool_attempt_count.unwrap_or_default() > 0
        && real_attempt_rows.is_empty()
        && pseudo_attempt_rows.is_empty();
    let timeline_attempt_count = attempts.len();
    let response = InvocationWorkflowDetailResponse {
        hero: build_workflow_hero(&record, payload_value.as_ref(), timeline_attempt_count),
        timeline: build_workflow_timeline_entries(
            &record,
            &attempts,
            route_only_attempt.as_ref(),
            failure_entry,
        ),
        reconstructed: identity.timeline_json.is_none(),
        partial,
        partial_reason: partial.then(|| "attempt_rows_missing".to_string()),
    };
    Ok(Json(response))
}

#[derive(Debug, FromRow)]
pub(crate) struct InvocationResponseBodyRow {
    pub(crate) id: i64,
    pub(crate) invoke_id: String,
    pub(crate) payload: Option<String>,
    pub(crate) raw_response: String,
    pub(crate) request_raw_path: Option<String>,
    pub(crate) request_raw_size: Option<i64>,
    pub(crate) request_raw_truncated: Option<i64>,
    pub(crate) request_raw_truncated_reason: Option<String>,
    pub(crate) response_raw_path: Option<String>,
    pub(crate) response_raw_size: Option<i64>,
    pub(crate) response_raw_truncated: Option<i64>,
    pub(crate) response_raw_truncated_reason: Option<String>,
    pub(crate) detail_level: String,
    pub(crate) detail_prune_reason: Option<String>,
    pub(crate) response_content_encoding: Option<String>,
    pub(crate) failure_class: Option<String>,
    pub(crate) upstream_request_id: Option<String>,
    pub(crate) attempt_public_id: Option<String>,
}

pub(crate) fn is_abnormal_invocation_failure(failure_class: Option<&str>) -> bool {
    matches!(
        failure_class
            .map(str::trim)
            .filter(|value| !value.is_empty()),
        Some("service_failure" | "client_failure" | "client_abort")
    )
}

pub(crate) fn truncate_response_preview_text(value: &str) -> (String, bool) {
    let mut end = value.len();
    let mut count = 0usize;
    for (index, _) in value.char_indices() {
        if count == INVOCATION_RESPONSE_BODY_PREVIEW_CHAR_LIMIT {
            end = index;
            break;
        }
        count += 1;
    }
    if count < INVOCATION_RESPONSE_BODY_PREVIEW_CHAR_LIMIT {
        return (value.to_string(), false);
    }
    (value[..end].to_string(), true)
}

pub(crate) fn raw_response_fallback_reason(row: &InvocationResponseBodyRow) -> String {
    if row.attempt_public_id.is_some() && row.response_raw_path.is_none() {
        "attempt_response_body_not_captured".to_string()
    } else if row.detail_level == DETAIL_LEVEL_STRUCTURED_ONLY {
        "detail_pruned".to_string()
    } else if row.response_raw_truncated.unwrap_or_default() != 0 {
        row.response_raw_truncated_reason
            .as_deref()
            .filter(|value| !value.trim().is_empty())
            .map(|reason| format!("preview_only:{reason}"))
            .unwrap_or_else(|| "preview_only".to_string())
    } else {
        "missing_body".to_string()
    }
}

pub(crate) fn raw_request_fallback_reason(row: &InvocationResponseBodyRow) -> String {
    if row.detail_level == DETAIL_LEVEL_STRUCTURED_ONLY {
        "detail_pruned".to_string()
    } else if row.request_raw_truncated.unwrap_or_default() != 0 {
        row.request_raw_truncated_reason
            .as_deref()
            .filter(|value| !value.trim().is_empty())
            .map(ToOwned::to_owned)
            .unwrap_or_else(|| "capture_unavailable".to_string())
    } else {
        "missing_body".to_string()
    }
}

pub(crate) fn resolve_request_body_text_from_row(
    row: &InvocationResponseBodyRow,
    raw_path_fallback_root: Option<&Path>,
) -> Result<(String, bool), String> {
    let Some(path) = row.request_raw_path.as_deref() else {
        return Err(raw_request_fallback_reason(row));
    };

    match read_proxy_raw_bytes(path, raw_path_fallback_root) {
        Ok(bytes) => Ok((String::from_utf8_lossy(&bytes).to_string(), true)),
        Err(err) if err.kind() == io::ErrorKind::NotFound => Err("raw_file_missing".to_string()),
        Err(err) => Err(format!("raw_file_unreadable:{err}")),
    }
}

pub(crate) fn resolve_response_body_text_from_row(
    row: &InvocationResponseBodyRow,
    raw_path_fallback_root: Option<&Path>,
) -> Result<(String, bool), String> {
    if let Some(path) = row.response_raw_path.as_deref() {
        match read_proxy_raw_bytes(path, raw_path_fallback_root) {
            Ok(bytes) => {
                let (decoded, _) = decode_response_payload_for_usage(
                    &bytes,
                    row.response_content_encoding.as_deref(),
                );
                return Ok((String::from_utf8_lossy(decoded.as_ref()).to_string(), true));
            }
            Err(err) if err.kind() == io::ErrorKind::NotFound => {
                let raw_preview = row.raw_response.trim();
                let preview_len = row.raw_response.len() as i64;
                if !raw_preview.is_empty()
                    && row.response_raw_size.unwrap_or(preview_len) <= preview_len
                {
                    return Ok((row.raw_response.clone(), false));
                }
                return Err("raw_file_missing".to_string());
            }
            Err(err) => {
                let raw_preview = row.raw_response.trim();
                let preview_len = row.raw_response.len() as i64;
                if !raw_preview.is_empty()
                    && row.response_raw_size.unwrap_or(preview_len) <= preview_len
                {
                    return Ok((row.raw_response.clone(), false));
                }
                return Err(format!("raw_file_unreadable:{err}"));
            }
        }
    }

    let raw_preview = row.raw_response.trim();
    if raw_preview.is_empty() {
        return Err(raw_response_fallback_reason(row));
    }

    let preview_len = row.raw_response.len() as i64;
    let fits_in_preview = row.response_raw_size.unwrap_or(preview_len) <= preview_len;
    if fits_in_preview && row.response_raw_truncated.unwrap_or_default() == 0 {
        return Ok((row.raw_response.clone(), false));
    }

    Err(raw_response_fallback_reason(row))
}

pub(crate) async fn fetch_invocation_response_body_row_by_id(
    pool: &Pool<Sqlite>,
    id: i64,
) -> Result<Option<InvocationResponseBodyRow>, ApiError> {
    let sql = format!(
        "SELECT \
         id, \
         invoke_id, \
         payload, \
         raw_response, \
         request_raw_path, \
         request_raw_size, \
         request_raw_truncated, \
         request_raw_truncated_reason, \
         response_raw_path, \
         response_raw_size, \
         response_raw_truncated, \
         response_raw_truncated_reason, \
         detail_level, \
         detail_prune_reason, \
         {response_content_encoding} AS response_content_encoding, \
         {resolved_failure} AS failure_class, \
         NULL AS upstream_request_id, \
         NULL AS attempt_public_id \
         FROM codex_invocations \
         WHERE id = ?1 \
         LIMIT 1",
        response_content_encoding = INVOCATION_RESPONSE_CONTENT_ENCODING_SQL,
        resolved_failure = INVOCATION_RESOLVED_FAILURE_CLASS_SQL,
    );

    sqlx::query_as::<_, InvocationResponseBodyRow>(&sql)
        .bind(id)
        .fetch_optional(pool)
        .await
        .map_err(ApiError::from)
}

fn build_request_body_capture_summary(
    row: &InvocationResponseBodyRow,
    capture_source: Option<&str>,
) -> Value {
    json!({
        "source": capture_source,
        "size": row.request_raw_size,
        "truncated": row.request_raw_truncated.unwrap_or_default() != 0,
        "truncatedReason": row.request_raw_truncated_reason.clone(),
        "detailLevel": Some(row.detail_level.clone()),
        "detailPruneReason": row.detail_prune_reason.clone(),
    })
}

fn build_response_body_capture_summary(
    row: &InvocationResponseBodyRow,
    capture_source: Option<&str>,
) -> Value {
    json!({
        "source": capture_source,
        "size": row.response_raw_size,
        "truncated": row.response_raw_truncated.unwrap_or_default() != 0,
        "truncatedReason": row.response_raw_truncated_reason.clone(),
        "detailLevel": Some(row.detail_level.clone()),
        "detailPruneReason": row.detail_prune_reason.clone(),
    })
}

fn build_request_body_routing_snapshot(
    row: &InvocationResponseBodyRow,
    payload: Option<&Value>,
) -> Value {
    json!({
        "routeMode": payload_string(payload, &["routeMode"]),
        "upstreamScope": payload_string(payload, &["upstreamScope"]),
        "stickyKey": payload_string(payload, &["stickyKey"]),
        "promptCacheKey": payload_string(payload, &["promptCacheKey"]),
        "proxyDisplayName": payload_string(payload, &["proxyDisplayName"]),
        "clientFingerprint": payload_string(payload, &["clientFingerprint"]),
        "clientHeaderFingerprints": payload_clone(payload, &["clientHeaderFingerprints"]),
        "oauthForwardedHeaderNames": payload_string_array(payload, &["oauthForwardedHeaderNames"]),
        "oauthPromptCacheHeaderForwarded": payload_bool(payload, &["oauthPromptCacheHeaderForwarded"]),
        "client": build_request_client_snapshot(payload),
        "invokeId": Some(row.invoke_id.clone()),
    })
}

fn build_response_body_header_snapshot(
    row: &InvocationResponseBodyRow,
    payload: Option<&Value>,
) -> Value {
    json!({
        "contentEncoding": row
            .response_content_encoding
            .clone()
            .or_else(|| payload_string(payload, &["responseContentEncoding"])),
        "contentEncodingChain": payload_string(payload, &["contentEncodingChain"]),
        "upstreamRequestId": row
            .upstream_request_id
            .clone()
            .or_else(|| payload_string(payload, &["upstreamRequestId"])),
        "cvmInvokeId": Some(row.invoke_id.clone()),
    })
}

fn build_request_body_response(
    row: &InvocationResponseBodyRow,
    raw_path_fallback_root: Option<&Path>,
) -> InvocationResponseBodyResponse {
    let payload = parse_optional_json_value(row.payload.as_deref());
    let headers = Some(build_request_header_snapshot(payload.as_ref()));
    let routing = Some(build_request_body_routing_snapshot(row, payload.as_ref()));
    match resolve_request_body_text_from_row(row, raw_path_fallback_root) {
        Ok((body_text, from_full_body)) => InvocationResponseBodyResponse {
            available: true,
            body_text: Some(body_text),
            unavailable_reason: None,
            headers,
            routing,
            body_size: row.request_raw_size,
            body_truncated: Some(row.request_raw_truncated.unwrap_or_default() != 0),
            body_truncated_reason: row.request_raw_truncated_reason.clone(),
            detail_level: Some(row.detail_level.clone()),
            detail_prune_reason: row.detail_prune_reason.clone(),
            capture_source: Some(
                if from_full_body {
                    "raw_file"
                } else {
                    "preview"
                }
                .to_string(),
            ),
        },
        Err(reason) => InvocationResponseBodyResponse {
            available: false,
            body_text: None,
            unavailable_reason: Some(reason),
            headers,
            routing,
            body_size: row.request_raw_size,
            body_truncated: Some(row.request_raw_truncated.unwrap_or_default() != 0),
            body_truncated_reason: row.request_raw_truncated_reason.clone(),
            detail_level: Some(row.detail_level.clone()),
            detail_prune_reason: row.detail_prune_reason.clone(),
            capture_source: None,
        },
    }
}

fn build_response_body_response(
    row: &InvocationResponseBodyRow,
    raw_path_fallback_root: Option<&Path>,
) -> InvocationResponseBodyResponse {
    build_response_body_response_with_source(row, raw_path_fallback_root, None)
}

fn build_response_body_response_with_source(
    row: &InvocationResponseBodyRow,
    raw_path_fallback_root: Option<&Path>,
    capture_source_override: Option<&str>,
) -> InvocationResponseBodyResponse {
    let payload = parse_optional_json_value(row.payload.as_deref());
    let headers = Some(build_response_body_header_snapshot(row, payload.as_ref()));
    let routing = Some(build_response_delivery_snapshot(payload.as_ref()));
    match resolve_response_body_text_from_row(row, raw_path_fallback_root) {
        Ok((body_text, from_full_body)) => InvocationResponseBodyResponse {
            available: true,
            body_text: Some(body_text),
            unavailable_reason: None,
            headers,
            routing,
            body_size: row.response_raw_size,
            body_truncated: Some(row.response_raw_truncated.unwrap_or_default() != 0),
            body_truncated_reason: row.response_raw_truncated_reason.clone(),
            detail_level: Some(row.detail_level.clone()),
            detail_prune_reason: row.detail_prune_reason.clone(),
            capture_source: Some(
                if from_full_body {
                    capture_source_override.unwrap_or("raw_file")
                } else {
                    "preview"
                }
                .to_string(),
            ),
        },
        Err(reason) => InvocationResponseBodyResponse {
            available: false,
            body_text: None,
            unavailable_reason: Some(reason),
            headers,
            routing,
            body_size: row.response_raw_size,
            body_truncated: Some(row.response_raw_truncated.unwrap_or_default() != 0),
            body_truncated_reason: row.response_raw_truncated_reason.clone(),
            detail_level: Some(row.detail_level.clone()),
            detail_prune_reason: row.detail_prune_reason.clone(),
            capture_source: None,
        },
    }
}

async fn fetch_invocation_attempt_response_body_row(
    pool: &Pool<Sqlite>,
    invocation_id: i64,
    attempt_public_id: &str,
) -> Result<Option<InvocationResponseBodyRow>, ApiError> {
    let sql = format!(
        r#"
        SELECT
            inv.id,
            inv.invoke_id,
            inv.payload,
            CASE
                WHEN inv.detail_level != 'structured_only'
                    AND attempts.attempt_index = (
                    SELECT MAX(final_attempt.attempt_index)
                    FROM pool_upstream_request_attempts AS final_attempt
                    WHERE final_attempt.invoke_id = attempts.invoke_id
                      AND final_attempt.occurred_at = attempts.occurred_at
                      AND final_attempt.status != 'budget_exhausted_final'
                ) THEN inv.raw_response
                ELSE ''
            END AS raw_response,
            inv.request_raw_path,
            inv.request_raw_size,
            inv.request_raw_truncated,
            inv.request_raw_truncated_reason,
            CASE
                WHEN inv.detail_level != 'structured_only'
                    AND attempts.response_raw_path IS NOT NULL THEN attempts.response_raw_path
                WHEN inv.detail_level != 'structured_only'
                    AND attempts.attempt_index = (
                    SELECT MAX(final_attempt.attempt_index)
                    FROM pool_upstream_request_attempts AS final_attempt
                    WHERE final_attempt.invoke_id = attempts.invoke_id
                      AND final_attempt.occurred_at = attempts.occurred_at
                      AND final_attempt.status != 'budget_exhausted_final'
                ) THEN inv.response_raw_path
                ELSE NULL
            END AS response_raw_path,
            CASE
                WHEN inv.detail_level != 'structured_only'
                    AND attempts.response_raw_path IS NOT NULL THEN attempts.response_raw_size
                WHEN inv.detail_level != 'structured_only'
                    AND attempts.attempt_index = (
                    SELECT MAX(final_attempt.attempt_index)
                    FROM pool_upstream_request_attempts AS final_attempt
                    WHERE final_attempt.invoke_id = attempts.invoke_id
                      AND final_attempt.occurred_at = attempts.occurred_at
                      AND final_attempt.status != 'budget_exhausted_final'
                ) THEN inv.response_raw_size
                ELSE NULL
            END AS response_raw_size,
            CASE
                WHEN inv.detail_level != 'structured_only'
                    AND attempts.response_raw_path IS NOT NULL THEN attempts.response_raw_truncated
                WHEN inv.detail_level != 'structured_only'
                    AND attempts.attempt_index = (
                    SELECT MAX(final_attempt.attempt_index)
                    FROM pool_upstream_request_attempts AS final_attempt
                    WHERE final_attempt.invoke_id = attempts.invoke_id
                      AND final_attempt.occurred_at = attempts.occurred_at
                      AND final_attempt.status != 'budget_exhausted_final'
                ) THEN inv.response_raw_truncated
                ELSE NULL
            END AS response_raw_truncated,
            CASE
                WHEN inv.detail_level != 'structured_only'
                    AND attempts.response_raw_path IS NOT NULL THEN attempts.response_raw_truncated_reason
                WHEN inv.detail_level != 'structured_only'
                    AND attempts.attempt_index = (
                    SELECT MAX(final_attempt.attempt_index)
                    FROM pool_upstream_request_attempts AS final_attempt
                    WHERE final_attempt.invoke_id = attempts.invoke_id
                      AND final_attempt.occurred_at = attempts.occurred_at
                      AND final_attempt.status != 'budget_exhausted_final'
                ) THEN inv.response_raw_truncated_reason
                ELSE NULL
            END AS response_raw_truncated_reason,
            inv.detail_level,
            inv.detail_prune_reason,
            CASE
                WHEN inv.detail_level != 'structured_only'
                    AND attempts.response_content_encoding IS NOT NULL THEN attempts.response_content_encoding
                WHEN inv.detail_level != 'structured_only'
                    AND attempts.attempt_index = (
                    SELECT MAX(final_attempt.attempt_index)
                    FROM pool_upstream_request_attempts AS final_attempt
                    WHERE final_attempt.invoke_id = attempts.invoke_id
                      AND final_attempt.occurred_at = attempts.occurred_at
                      AND final_attempt.status != 'budget_exhausted_final'
                ) THEN {response_content_encoding}
                ELSE NULL
            END AS response_content_encoding,
            {resolved_failure} AS failure_class,
            attempts.upstream_request_id AS upstream_request_id,
            attempts.attempt_public_id AS attempt_public_id
        FROM codex_invocations AS inv
        JOIN pool_upstream_request_attempts AS attempts
            ON attempts.invoke_id = inv.invoke_id
           AND attempts.occurred_at = inv.occurred_at
        WHERE inv.id = ?1
          AND attempts.attempt_public_id = ?2
        LIMIT 1
        "#,
        response_content_encoding = INVOCATION_RESPONSE_CONTENT_ENCODING_SQL,
        resolved_failure = invocation_resolved_failure_class_sql_for("inv"),
    );
    sqlx::query_as::<_, InvocationResponseBodyRow>(&sql)
        .bind(invocation_id)
        .bind(attempt_public_id)
        .fetch_optional(pool)
        .await
        .map_err(ApiError::from)
}

pub(crate) async fn fetch_invocation_record_detail(
    State(state): State<Arc<AppState>>,
    axum::extract::Path(id): axum::extract::Path<i64>,
) -> Result<Json<InvocationRecordDetailResponse>, ApiError> {
    let row = fetch_invocation_response_body_row_by_id(&state.pool, id)
        .await?
        .ok_or_else(|| ApiError::bad_request(anyhow!("record not found")))?;

    let abnormal_response_body = if is_abnormal_invocation_failure(row.failure_class.as_deref()) {
        match resolve_response_body_text_from_row(&row, state.config.database_path.parent()) {
            Ok((text, from_full_body)) => {
                let (preview_text, truncated) = truncate_response_preview_text(&text);
                Some(InvocationAbnormalResponseBodyPreview {
                    available: true,
                    preview_text: Some(preview_text),
                    has_more: truncated || from_full_body,
                    unavailable_reason: None,
                })
            }
            Err(reason) => Some(InvocationAbnormalResponseBodyPreview {
                available: false,
                preview_text: None,
                has_more: false,
                unavailable_reason: Some(reason),
            }),
        }
    } else {
        None
    };

    Ok(Json(InvocationRecordDetailResponse {
        id: row.id,
        abnormal_response_body,
    }))
}

pub(crate) async fn fetch_invocation_response_body(
    State(state): State<Arc<AppState>>,
    axum::extract::Path(id): axum::extract::Path<i64>,
) -> Result<Json<InvocationResponseBodyResponse>, ApiError> {
    let row = fetch_invocation_response_body_row_by_id(&state.pool, id)
        .await?
        .ok_or_else(|| ApiError::bad_request(anyhow!("record not found")))?;
    Ok(Json(build_response_body_response(
        &row,
        state.config.database_path.parent(),
    )))
}

pub(crate) async fn fetch_invocation_attempt_response_body(
    State(state): State<Arc<AppState>>,
    axum::extract::Path((id, attempt_public_id)): axum::extract::Path<(i64, String)>,
) -> Result<Json<InvocationResponseBodyResponse>, ApiError> {
    let row =
        fetch_invocation_attempt_response_body_row(&state.pool, id, attempt_public_id.as_str())
            .await?
            .ok_or_else(|| ApiError::bad_request(anyhow!("attempt not found")))?;
    let (has_attempt_capture, has_invocation_capture) = sqlx::query_as::<
        _,
        (Option<i64>, Option<i64>),
    >(
        "SELECT (inv.detail_level != 'structured_only' AND attempts.response_raw_path IS NOT NULL),
                (inv.detail_level != 'structured_only' AND inv.response_raw_path IS NOT NULL)
         FROM pool_upstream_request_attempts AS attempts
         JOIN codex_invocations AS inv
           ON inv.invoke_id = attempts.invoke_id
          AND inv.occurred_at = attempts.occurred_at
         WHERE inv.id = ?1
           AND attempts.attempt_public_id = ?2
         LIMIT 1",
    )
    .bind(id)
    .bind(attempt_public_id.as_str())
    .fetch_optional(&state.pool)
    .await?
    .unwrap_or_default();
    let has_attempt_capture = has_attempt_capture.unwrap_or_default() != 0;
    let has_invocation_capture = has_invocation_capture.unwrap_or_default() != 0;
    let source = Some(if has_attempt_capture {
        "attempt_raw_file"
    } else if has_invocation_capture && row.response_raw_path.is_some() {
        "invocation_raw_file"
    } else {
        "attempt_metrics"
    });
    Ok(Json(build_response_body_response_with_source(
        &row,
        state.config.database_path.parent(),
        source,
    )))
}

pub(crate) async fn fetch_invocation_request_body(
    State(state): State<Arc<AppState>>,
    axum::extract::Path(id): axum::extract::Path<i64>,
) -> Result<Json<InvocationResponseBodyResponse>, ApiError> {
    let row = fetch_invocation_response_body_row_by_id(&state.pool, id)
        .await?
        .ok_or_else(|| ApiError::bad_request(anyhow!("record not found")))?;
    Ok(Json(build_request_body_response(
        &row,
        state.config.database_path.parent(),
    )))
}

pub(crate) async fn fetch_invocation_summary(
    State(state): State<Arc<AppState>>,
    Query(params): Query<ListQuery>,
) -> Result<Json<InvocationSummaryResponse>, ApiError> {
    fetch_invocation_summary_with_runtime_overlay(state, params, None).await
}

pub(crate) async fn fetch_invocation_summary_with_runtime_overlay(
    state: Arc<AppState>,
    params: ListQuery,
    runtime_overlay_override: Option<Vec<ApiInvocation>>,
) -> Result<Json<InvocationSummaryResponse>, ApiError> {
    let request = build_resolved_invocation_list_request(
        &state.pool,
        &params,
        state.config.list_limit_max as i64,
    )
    .await?;
    let source_scope = resolve_default_source_scope(&state.pool).await?;
    let runtime_records =
        runtime_overlay_override.unwrap_or_else(|| runtime_overlay_snapshot(state.as_ref()));
    let mut tx = state.pool.begin().await?;
    let snapshot_id = request
        .snapshot_id
        .unwrap_or(resolve_invocation_snapshot_id_on_connection(&mut tx, source_scope).await?);

    let totals_sql = format!(
        "SELECT \
         COUNT(*) AS total_count, \
         COALESCE(SUM(CASE WHEN {resolved_failure} = 'none' AND ({status_norm} IN ('success', 'completed', '{warning_success}') OR ({status_norm} = 'http_200' AND LOWER(TRIM(COALESCE(error_message, ''))) = '')) THEN 1 ELSE 0 END), 0) AS success_count, \
         COALESCE(SUM(CASE WHEN {resolved_failure} IN ('service_failure', 'client_failure', 'client_abort') THEN 1 ELSE 0 END), 0) AS failure_count, \
         COALESCE(SUM(total_tokens), 0) AS total_tokens, \
         COALESCE(SUM(cost), 0.0) AS total_cost, \
         COALESCE(SUM(MAX(COALESCE(input_tokens, 0) - COALESCE(cache_input_tokens, 0), 0)), 0) AS cache_write_tokens, \
         COALESCE(SUM(cache_input_tokens), 0) AS cache_input_tokens, \
         COALESCE(SUM(output_tokens), 0) AS output_tokens, \
         MAX(CASE WHEN total_tokens >= 0 THEN total_tokens END) AS max_total_tokens \
         FROM codex_invocations WHERE 1 = 1",
        status_norm = INVOCATION_STATUS_NORMALIZED_SQL,
        resolved_failure = INVOCATION_RESOLVED_FAILURE_CLASS_SQL,
        warning_success = INVOCATION_STATUS_WARNING_SUCCESS,
    );
    let mut totals_query = QueryBuilder::new(totals_sql);
    apply_invocation_records_filters(
        &mut totals_query,
        &request.filters,
        source_scope,
        Some(SnapshotConstraint::UpTo(snapshot_id)),
    );
    let totals = totals_query
        .build_query_as::<InvocationSummaryAggRow>()
        .fetch_one(&mut *tx)
        .await?;

    let network = query_invocation_network_summary_on_connection(
        &mut tx,
        &request.filters,
        source_scope,
        snapshot_id,
    )
    .await?;

    let exception = query_invocation_exception_summary_on_connection(
        &mut tx,
        &request.filters,
        source_scope,
        snapshot_id,
    )
    .await?;

    let new_records_count = query_invocation_new_records_count_on_connection(
        &mut tx,
        &request.filters,
        source_scope,
        snapshot_id,
    )
    .await?;

    let runtime_overlay_delta = if request.snapshot_id.is_none() {
        let db_runtime_keys = query_current_runtime_db_keys_on_connection(
            &mut tx,
            &request.filters,
            source_scope,
            Some(SnapshotConstraint::UpTo(snapshot_id)),
        )
        .await?;
        let db_terminal_keys = query_terminal_db_keys_for_runtime_records_on_connection(
            &mut tx,
            &runtime_records,
            Some(SnapshotConstraint::UpTo(snapshot_id)),
        )
        .await?;
        let (delta, runtime_new_count, stale_db_runtime_count) = runtime_overlay_total_delta(
            &request,
            source_scope,
            &runtime_records,
            &db_runtime_keys,
            &db_terminal_keys,
        );
        if runtime_new_count > 0 || stale_db_runtime_count > 0 {
            debug!(
                endpoint = "invocation_summary",
                runtime_overlay_row_count = runtime_new_count,
                stale_db_runtime_total_count = stale_db_runtime_count,
                "adjusted current summary count with memory runtime overlay"
            );
        }
        delta
    } else {
        RuntimeSummaryOverlayDelta::default()
    };
    let total_count = (totals.total_count + runtime_overlay_delta.total_count).max(0);
    let success_count = (totals.success_count + runtime_overlay_delta.success_count).max(0);
    let failure_count = (totals.failure_count + runtime_overlay_delta.failure_count).max(0);
    let total_tokens = (totals.total_tokens + runtime_overlay_delta.total_tokens).max(0);
    let total_cost = totals.total_cost + runtime_overlay_delta.total_cost;
    let cache_write_tokens =
        (totals.cache_write_tokens + runtime_overlay_delta.cache_write_tokens).max(0);
    let cache_input_tokens =
        (totals.cache_input_tokens + runtime_overlay_delta.cache_input_tokens).max(0);
    let output_tokens = (totals.output_tokens + runtime_overlay_delta.output_tokens).max(0);
    let max_tokens_per_request = match (
        totals.max_total_tokens,
        runtime_overlay_delta.max_total_tokens,
    ) {
        (Some(left), Some(right)) => Some(left.max(right)),
        (Some(left), None) => Some(left),
        (None, Some(right)) => Some(right),
        (None, None) => None,
    };
    let max_total_ms = match (network.max_total_ms, runtime_overlay_delta.max_total_ms) {
        (Some(left), Some(right)) => Some(left.max(right)),
        (Some(left), None) => Some(left),
        (None, Some(right)) => Some(right),
        (None, None) => None,
    };
    let avg_tokens_per_request = if total_count <= 0 {
        0.0
    } else {
        total_tokens as f64 / total_count as f64
    };
    let exception_summary = InvocationExceptionSummary {
        failure_count: (exception.failure_count + runtime_overlay_delta.failure_count).max(0),
        service_failure_count: (exception.service_failure_count
            + runtime_overlay_delta.service_failure_count)
            .max(0),
        client_failure_count: (exception.client_failure_count
            + runtime_overlay_delta.client_failure_count)
            .max(0),
        client_abort_count: (exception.client_abort_count
            + runtime_overlay_delta.client_abort_count)
            .max(0),
        actionable_failure_count: (exception.actionable_failure_count
            + runtime_overlay_delta.service_failure_count)
            .max(0),
    };

    let response = InvocationSummaryResponse {
        snapshot_id,
        new_records_count,
        total_count,
        success_count,
        failure_count,
        total_tokens,
        total_cost,
        token: InvocationTokenSummary {
            request_count: total_count,
            total_tokens,
            avg_tokens_per_request,
            cache_write_tokens,
            cache_input_tokens,
            output_tokens,
            total_cost,
            max_tokens_per_request,
        },
        network: InvocationNetworkSummary {
            max_total_ms,
            ..network
        },
        exception: exception_summary,
    };
    tx.commit().await?;
    Ok(Json(response))
}

async fn build_invocation_summary_on_connection(
    request: &InvocationListRequest,
    source_scope: InvocationSourceScope,
    snapshot_id: i64,
    runtime_records: &[ApiInvocation],
    connection: &mut SqliteConnection,
) -> Result<InvocationSummaryResponse, ApiError> {
    let totals_sql = format!(
        "SELECT \
         COUNT(*) AS total_count, \
         COALESCE(SUM(CASE WHEN {resolved_failure} = 'none' AND ({status_norm} IN ('success', 'completed', '{warning_success}') OR ({status_norm} = 'http_200' AND LOWER(TRIM(COALESCE(error_message, ''))) = '')) THEN 1 ELSE 0 END), 0) AS success_count, \
         COALESCE(SUM(CASE WHEN {resolved_failure} IN ('service_failure', 'client_failure', 'client_abort') THEN 1 ELSE 0 END), 0) AS failure_count, \
         COALESCE(SUM(total_tokens), 0) AS total_tokens, \
         COALESCE(SUM(cost), 0.0) AS total_cost, \
         COALESCE(SUM(MAX(COALESCE(input_tokens, 0) - COALESCE(cache_input_tokens, 0), 0)), 0) AS cache_write_tokens, \
         COALESCE(SUM(cache_input_tokens), 0) AS cache_input_tokens, \
         COALESCE(SUM(output_tokens), 0) AS output_tokens, \
         MAX(CASE WHEN total_tokens >= 0 THEN total_tokens END) AS max_total_tokens \
         FROM codex_invocations WHERE 1 = 1",
        status_norm = INVOCATION_STATUS_NORMALIZED_SQL,
        resolved_failure = INVOCATION_RESOLVED_FAILURE_CLASS_SQL,
        warning_success = INVOCATION_STATUS_WARNING_SUCCESS,
    );
    let mut totals_query = QueryBuilder::new(totals_sql);
    apply_invocation_records_filters(
        &mut totals_query,
        &request.filters,
        source_scope,
        Some(SnapshotConstraint::UpTo(snapshot_id)),
    );
    let totals = totals_query
        .build_query_as::<InvocationSummaryAggRow>()
        .fetch_one(&mut *connection)
        .await?;
    let network = query_invocation_network_summary_on_connection(
        connection,
        &request.filters,
        source_scope,
        snapshot_id,
    )
    .await?;
    let exception = query_invocation_exception_summary_on_connection(
        connection,
        &request.filters,
        source_scope,
        snapshot_id,
    )
    .await?;
    let new_records_count = query_invocation_new_records_count_on_connection(
        connection,
        &request.filters,
        source_scope,
        snapshot_id,
    )
    .await?;

    let runtime_overlay_delta = if request.snapshot_id.is_none() {
        let db_runtime_keys = query_current_runtime_db_keys_on_connection(
            connection,
            &request.filters,
            source_scope,
            Some(SnapshotConstraint::UpTo(snapshot_id)),
        )
        .await?;
        let db_terminal_keys = query_terminal_db_keys_for_runtime_records_on_connection(
            connection,
            runtime_records,
            Some(SnapshotConstraint::UpTo(snapshot_id)),
        )
        .await?;
        runtime_overlay_total_delta(
            request,
            source_scope,
            runtime_records,
            &db_runtime_keys,
            &db_terminal_keys,
        )
        .0
    } else {
        RuntimeSummaryOverlayDelta::default()
    };
    let total_count = (totals.total_count + runtime_overlay_delta.total_count).max(0);
    let success_count = (totals.success_count + runtime_overlay_delta.success_count).max(0);
    let failure_count = (totals.failure_count + runtime_overlay_delta.failure_count).max(0);
    let total_tokens = (totals.total_tokens + runtime_overlay_delta.total_tokens).max(0);
    let total_cost = totals.total_cost + runtime_overlay_delta.total_cost;
    let cache_write_tokens =
        (totals.cache_write_tokens + runtime_overlay_delta.cache_write_tokens).max(0);
    let cache_input_tokens =
        (totals.cache_input_tokens + runtime_overlay_delta.cache_input_tokens).max(0);
    let output_tokens = (totals.output_tokens + runtime_overlay_delta.output_tokens).max(0);
    let max_tokens_per_request = match (
        totals.max_total_tokens,
        runtime_overlay_delta.max_total_tokens,
    ) {
        (Some(left), Some(right)) => Some(left.max(right)),
        (Some(left), None) => Some(left),
        (None, Some(right)) => Some(right),
        (None, None) => None,
    };
    let max_total_ms = match (network.max_total_ms, runtime_overlay_delta.max_total_ms) {
        (Some(left), Some(right)) => Some(left.max(right)),
        (Some(left), None) => Some(left),
        (None, Some(right)) => Some(right),
        (None, None) => None,
    };
    let avg_tokens_per_request = if total_count <= 0 {
        0.0
    } else {
        total_tokens as f64 / total_count as f64
    };
    let exception = InvocationExceptionSummary {
        failure_count: (exception.failure_count + runtime_overlay_delta.failure_count).max(0),
        service_failure_count: (exception.service_failure_count
            + runtime_overlay_delta.service_failure_count)
            .max(0),
        client_failure_count: (exception.client_failure_count
            + runtime_overlay_delta.client_failure_count)
            .max(0),
        client_abort_count: (exception.client_abort_count
            + runtime_overlay_delta.client_abort_count)
            .max(0),
        actionable_failure_count: (exception.actionable_failure_count
            + runtime_overlay_delta.service_failure_count)
            .max(0),
    };
    Ok(InvocationSummaryResponse {
        snapshot_id,
        new_records_count,
        total_count,
        success_count,
        failure_count,
        total_tokens,
        total_cost,
        token: InvocationTokenSummary {
            request_count: total_count,
            total_tokens,
            avg_tokens_per_request,
            cache_write_tokens,
            cache_input_tokens,
            output_tokens,
            total_cost,
            max_tokens_per_request,
        },
        network: InvocationNetworkSummary {
            max_total_ms,
            ..network
        },
        exception,
    })
}

pub(crate) async fn fetch_invocation_history_overview_with_runtime_overlay(
    state: Arc<AppState>,
    params: ListQuery,
    runtime_overlay_records: Vec<ApiInvocation>,
    max_records: usize,
) -> Result<InvocationHistoryOverviewResponse, ApiError> {
    let request = build_resolved_invocation_list_request(
        &state.pool,
        &params,
        state.config.list_limit_max as i64,
    )
    .await?;
    let source_scope = resolve_default_source_scope(&state.pool).await?;
    let pricing_catalog = state.pricing_catalog.read().await.clone();
    let mut tx = state.pool.begin().await?;
    let snapshot_id = request
        .snapshot_id
        .unwrap_or(resolve_invocation_snapshot_id_on_connection(&mut tx, source_scope).await?);
    let summary = build_invocation_summary_on_connection(
        &request,
        source_scope,
        snapshot_id,
        &runtime_overlay_records,
        &mut tx,
    )
    .await?;
    let chart_total = summary.total_count;
    let mut records = Vec::new();
    let mut page = 1_i64;
    while records.len() < max_records {
        let mut page_request = request.clone();
        page_request.page = page;
        let response = list_invocation_page_with_runtime_overlay_on_connection(
            &page_request,
            source_scope,
            snapshot_id,
            &runtime_overlay_records,
            &pricing_catalog,
            &mut tx,
        )
        .await?;
        let received_count = response.records.len();
        if received_count == 0 {
            break;
        }
        let remaining = max_records - records.len();
        records.extend(response.records.into_iter().take(remaining));
        if records.len() >= chart_total as usize || received_count < page_request.page_size as usize
        {
            break;
        }
        page += 1;
    }
    let mut chart_range_start = records
        .iter()
        .map(|record| record.occurred_at.clone())
        .min();
    let mut chart_range_end = records
        .iter()
        .map(|record| record.occurred_at.clone())
        .max();
    if chart_total as usize > records.len() {
        let overview_page_size = request.page_size.max(1);
        let oldest_page = (chart_total + overview_page_size - 1) / overview_page_size;
        let mut oldest_request = request;
        oldest_request.page = oldest_page.max(1);
        let oldest_response = list_invocation_page_with_runtime_overlay_on_connection(
            &oldest_request,
            source_scope,
            snapshot_id,
            &runtime_overlay_records,
            &pricing_catalog,
            &mut tx,
        )
        .await?;
        for record in oldest_response.records {
            chart_range_start = Some(
                chart_range_start.map_or(record.occurred_at.clone(), |current| {
                    current.min(record.occurred_at.clone())
                }),
            );
            chart_range_end = Some(
                chart_range_end.map_or(record.occurred_at.clone(), |current| {
                    current.max(record.occurred_at.clone())
                }),
            );
        }
    }
    tx.commit().await?;
    Ok(InvocationHistoryOverviewResponse {
        summary,
        chart_is_sampled: chart_total as usize > records.len(),
        records,
        chart_total,
        chart_range_start,
        chart_range_end,
    })
}

pub(crate) async fn fetch_invocation_new_records_count(
    State(state): State<Arc<AppState>>,
    Query(params): Query<ListQuery>,
) -> Result<Json<InvocationNewRecordsCountResponse>, ApiError> {
    let request = build_resolved_invocation_list_request(
        &state.pool,
        &params,
        state.config.list_limit_max as i64,
    )
    .await?;
    let source_scope = resolve_default_source_scope(&state.pool).await?;
    let snapshot_id = request
        .snapshot_id
        .ok_or_else(|| ApiError::bad_request(anyhow!("snapshotId is required")))?;
    let new_records_count = query_invocation_new_records_count(
        &state.pool,
        &request.filters,
        source_scope,
        snapshot_id,
    )
    .await?;

    Ok(Json(InvocationNewRecordsCountResponse {
        snapshot_id,
        new_records_count,
    }))
}

pub(crate) async fn fetch_invocation_suggestions(
    State(state): State<Arc<AppState>>,
    Query(params): Query<ListQuery>,
) -> Result<Json<InvocationSuggestionsResponse>, ApiError> {
    const SUGGESTION_LIMIT: i64 = 30;
    let request = build_resolved_invocation_list_request(
        &state.pool,
        &params,
        state.config.list_limit_max as i64,
    )
    .await?;
    let filters = request.filters;
    let source_scope = resolve_default_source_scope(&state.pool).await?;
    let snapshot = request.snapshot_id.map(SnapshotConstraint::UpTo);
    let suggest_field = InvocationSuggestionField::parse(params.suggest_field.as_deref())?;
    let suggest_query = normalize_query_text(params.suggest_query.as_deref());

    if let Some(field) = suggest_field {
        let scoped_filters = field.clear_field_filter(&filters);
        let bucket = match field {
            InvocationSuggestionField::UpstreamAccount => {
                query_invocation_upstream_account_suggestion_bucket(
                    &state.pool,
                    &scoped_filters,
                    source_scope,
                    snapshot,
                    suggest_query.as_deref(),
                    SUGGESTION_LIMIT,
                )
                .await?
            }
            _ => {
                let sql_expr = field.sql_expr();
                query_invocation_suggestion_bucket(
                    &state.pool,
                    &scoped_filters,
                    source_scope,
                    snapshot,
                    &sql_expr,
                    suggest_query.as_deref(),
                    SUGGESTION_LIMIT,
                )
                .await?
            }
        };
        return Ok(Json(suggestion_response_for_field(field, bucket)));
    }

    let model = query_invocation_suggestion_bucket(
        &state.pool,
        &InvocationRecordsFilters {
            model: None,
            ..filters.clone()
        },
        source_scope,
        snapshot,
        "model",
        None,
        SUGGESTION_LIMIT,
    )
    .await?;
    let request_model = query_invocation_suggestion_bucket(
        &state.pool,
        &InvocationRecordsFilters {
            model: None,
            model_values: Vec::new(),
            ..filters.clone()
        },
        source_scope,
        snapshot,
        &invocation_model_sql_expr(InvocationModelTarget::Request),
        None,
        SUGGESTION_LIMIT,
    )
    .await?;
    let response_model = query_invocation_suggestion_bucket(
        &state.pool,
        &InvocationRecordsFilters {
            model: None,
            model_values: Vec::new(),
            ..filters.clone()
        },
        source_scope,
        snapshot,
        &invocation_model_sql_expr(InvocationModelTarget::Response),
        None,
        SUGGESTION_LIMIT,
    )
    .await?;
    let endpoint = query_invocation_suggestion_bucket(
        &state.pool,
        &InvocationRecordsFilters {
            endpoint: None,
            ..filters.clone()
        },
        source_scope,
        snapshot,
        INVOCATION_ENDPOINT_SQL,
        None,
        SUGGESTION_LIMIT,
    )
    .await?;
    let failure_kind = query_invocation_suggestion_bucket(
        &state.pool,
        &InvocationRecordsFilters {
            failure_kind: None,
            ..filters.clone()
        },
        source_scope,
        snapshot,
        INVOCATION_FAILURE_KIND_SQL,
        None,
        SUGGESTION_LIMIT,
    )
    .await?;
    let sticky_key = query_invocation_suggestion_bucket(
        &state.pool,
        &InvocationRecordsFilters {
            sticky_key: None,
            ..filters.clone()
        },
        source_scope,
        snapshot,
        INVOCATION_STICKY_KEY_SQL,
        None,
        SUGGESTION_LIMIT,
    )
    .await?;
    let prompt_cache_key = query_invocation_suggestion_bucket(
        &state.pool,
        &InvocationRecordsFilters {
            prompt_cache_key: None,
            ..filters.clone()
        },
        source_scope,
        snapshot,
        INVOCATION_PROMPT_CACHE_KEY_SQL,
        None,
        SUGGESTION_LIMIT,
    )
    .await?;
    let requester_ip = query_invocation_suggestion_bucket(
        &state.pool,
        &InvocationRecordsFilters {
            requester_ip: None,
            ..filters.clone()
        },
        source_scope,
        snapshot,
        INVOCATION_REQUESTER_IP_SQL,
        None,
        SUGGESTION_LIMIT,
    )
    .await?;
    let proxy_display_name = query_invocation_suggestion_bucket(
        &state.pool,
        &InvocationRecordsFilters {
            proxy_display_name: None,
            ..filters.clone()
        },
        source_scope,
        snapshot,
        INVOCATION_PROXY_DISPLAY_SQL,
        None,
        SUGGESTION_LIMIT,
    )
    .await?;
    let upstream_account = query_invocation_upstream_account_suggestion_bucket(
        &state.pool,
        &InvocationRecordsFilters {
            upstream_account_id: None,
            ..filters.clone()
        },
        source_scope,
        snapshot,
        None,
        SUGGESTION_LIMIT,
    )
    .await?;
    let service_tier = query_invocation_suggestion_bucket(
        &state.pool,
        &InvocationRecordsFilters {
            service_tier: None,
            ..filters.clone()
        },
        source_scope,
        snapshot,
        INVOCATION_SERVICE_TIER_SQL,
        None,
        SUGGESTION_LIMIT,
    )
    .await?;
    let reasoning_effort = query_invocation_suggestion_bucket(
        &state.pool,
        &InvocationRecordsFilters {
            reasoning_effort: None,
            ..filters.clone()
        },
        source_scope,
        snapshot,
        INVOCATION_REASONING_EFFORT_SQL,
        None,
        SUGGESTION_LIMIT,
    )
    .await?;

    Ok(Json(InvocationSuggestionsResponse {
        model,
        request_model,
        response_model,
        endpoint,
        failure_kind,
        sticky_key,
        prompt_cache_key,
        requester_ip,
        proxy_display_name,
        upstream_account,
        service_tier,
        reasoning_effort,
    }))
}

pub(crate) async fn fetch_stats(
    State(state): State<Arc<AppState>>,
) -> Result<Json<StatsResponse>, ApiError> {
    let source_scope = resolve_default_source_scope(&state.pool).await?;
    let totals = query_combined_totals(&state.pool, StatsFilter::All, source_scope).await?;
    let mut response = totals.into_response();
    response.non_success_cost = Some(totals.non_success_cost);
    let augmentation = load_summary_live_augmentation(
        state.as_ref(),
        source_scope,
        None,
        None,
        SummaryLiveAugmentationPolicy {
            include_in_progress: true,
            include_non_success_tokens: false,
        },
        None,
    )
    .await?;
    apply_summary_live_augmentation(&mut response, augmentation);
    response.maintenance = Some(load_stats_maintenance_response(state.as_ref()).await?);
    Ok(Json(response))
}

pub(crate) async fn load_in_progress_conversation_count(
    state: &AppState,
    source_scope: InvocationSourceScope,
    upstream_account_id: Option<i64>,
) -> Result<i64, ApiError> {
    Ok(
        load_in_progress_summary_snapshot(state, source_scope, upstream_account_id)
            .await?
            .in_progress_count,
    )
}

pub(crate) const SUMMARY_SNAPSHOT_MAX_STALE: Duration = Duration::from_secs(15);
pub(crate) const SUMMARY_SNAPSHOT_MAX_KEYS: usize = 48;
const SUMMARY_SNAPSHOT_REFRESH_INTERVAL: Duration = Duration::from_secs(5);
const SUMMARY_SNAPSHOT_EVENT_DEBOUNCE: Duration = Duration::from_millis(250);
const SUMMARY_SNAPSHOT_MIN_REFRESH_INTERVAL: Duration = Duration::from_secs(10);
// Do not turn a locked or overloaded SQLite database into a continuous sequence of timed-out
// full hydrations. Mutations remain coalesced as dirty while this bounded retry gate is active.
const SUMMARY_SNAPSHOT_FAILURE_RETRY_BACKOFF: Duration = Duration::from_secs(30);
// Reconcile before the 15-second serving budget expires; a timed-out build is discarded
// atomically and cannot expose a partial projection to the request path.
const SUMMARY_PROJECTION_BUILD_DEADLINE: Duration = Duration::from_secs(10);
const SUMMARY_PROJECTION_MAX_EXACT_RECORDS: usize = 50_000;
// Account and archive metadata are admission-controlled independently from exact invocation
// rows.  A refresh which cannot represent the durable cardinality fails closed and keeps the
// previous projection, rather than publishing a partial aggregate.
const SUMMARY_PROJECTION_MAX_ACCOUNTS: usize = 50_000;
const SUMMARY_PROJECTION_MAX_ARCHIVE_BATCHES: usize = 4_096;
const SUMMARY_PROJECTION_MAX_CANONICAL_BYTES: usize = 64 * 1024 * 1024;
// Rollup tables are compact but can still become unbounded when account/model cardinality
// grows. Count and size-limit their background hydration before materializing rows in memory.
const SUMMARY_PROJECTION_MAX_ROLLUP_ROWS: usize = 200_000;
const SUMMARY_PROJECTION_MAX_ROLLUP_BYTES: usize = 32 * 1024 * 1024;
const SUMMARY_PROJECTION_MIN_EXACT_HORIZON: ChronoDuration = ChronoDuration::hours(48);
// Summary duration/calendar ranges are backed by the configured live retention plus the
// archive grace used by the existing range readers.  Deriving this once from configuration
// keeps boundary hydration finite while covering every legal rolling window that can outlive
// the 48-hour exact tail; HTTP still reads only the resulting in-memory projection.
const SUMMARY_PROJECTION_ARCHIVE_GRACE_DAYS: u64 = 30;
// The public Summary UI exposes rolling windows through 1mo. Keep arbitrary parser inputs
// bounded at the HTTP contract so the projection never has to retain an unbounded set of
// partial-hour boundaries; longer requests fail before hub/SQLite access.
const SUMMARY_PROJECTION_MAX_DURATION: ChronoDuration = ChronoDuration::days(30);

fn summary_projection_exact_horizon(invocation_max_days: u64) -> ChronoDuration {
    let supported_days = invocation_max_days.saturating_add(SUMMARY_PROJECTION_ARCHIVE_GRACE_DAYS);
    ChronoDuration::days(supported_days.max(2) as i64).max(SUMMARY_PROJECTION_MIN_EXACT_HORIZON)
}

fn validate_summary_projection_window(
    query: &SummaryQuery,
    default_limit: i64,
) -> Result<(), ApiError> {
    if let SummaryWindow::Duration(duration) =
        parse_summary_window(query, default_limit).map_err(ApiError::bad_request)?
    {
        if duration <= ChronoDuration::zero() {
            return Err(ApiError::bad_request(anyhow!(
                "summary duration must be greater than zero"
            )));
        }
        if duration > SUMMARY_PROJECTION_MAX_DURATION {
            return Err(ApiError::bad_request(anyhow!(
                "summary duration exceeds the supported 30d window"
            )));
        }
        if duration > SUMMARY_PROJECTION_MIN_EXACT_HORIZON
            && duration.num_minutes() % ChronoDuration::days(1).num_minutes() != 0
        {
            return Err(ApiError::bad_request(anyhow!(
                "summary durations over 48h must use whole-day granularity"
            )));
        }
    }
    Ok(())
}

fn summary_projection_boundary_buckets(end: DateTime<Utc>) -> HashSet<i64> {
    let mut buckets = HashSet::new();
    let mut add_bucket = |timestamp: DateTime<Utc>| {
        buckets.insert(align_bucket_epoch(timestamp.timestamp(), 3_600, 0));
    };
    // These are the finite rolling windows exposed by the stats UI and the dashboard
    // bootstrap snapshots.  Keep their start/end partial hours exact even when the enclosing
    // projection range is much wider and the middle is served from hourly rollups.
    for days in 1..=30 {
        add_bucket(end - ChronoDuration::days(days));
    }
    for duration in [
        ChronoDuration::minutes(30),
        ChronoDuration::hours(1),
        ChronoDuration::hours(6),
        ChronoDuration::hours(12),
    ] {
        add_bucket(end - duration);
    }
    add_bucket(end);

    // Calendar boundaries belong to the request timezone, not an approximate UTC offset.  The
    // projection can serve for fifteen seconds, so cover the finite set of IANA timezone
    // boundaries at build time and again at the far edge of that serving interval.  This keeps
    // non-whole-hour zones, the date line, DST, and a just-crossed local day/week/month exact
    // without adding a per-request archive read.
    for boundary_now in [
        end,
        end + ChronoDuration::seconds(SUMMARY_SNAPSHOT_MAX_STALE.as_secs() as i64),
    ] {
        for timezone in TZ_VARIANTS {
            for spec in ["today", "yesterday", "thisWeek", "thisMonth"] {
                if let Some((start, end)) = named_range_bounds(spec, boundary_now, timezone) {
                    add_bucket(start);
                    add_bucket(end);
                }
            }
            if let Some((start, end)) = previous_full_days_range_bounds(7, boundary_now, timezone) {
                add_bucket(start);
                add_bucket(end);
            }
        }
    }
    buckets
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub(crate) struct SummarySnapshotKey {
    window: String,
    limit: Option<i64>,
    time_zone: String,
    upstream_account_id: Option<i64>,
}

impl SummarySnapshotKey {
    pub(crate) fn try_from_query(query: &SummaryQuery, default_limit: i64) -> Result<Self> {
        let (window, limit) = match parse_summary_window(query, default_limit)? {
            SummaryWindow::All => ("all".to_string(), None),
            SummaryWindow::Current(limit) => ("current".to_string(), Some(limit)),
            SummaryWindow::Duration(duration) => (format!("{}m", duration.num_minutes()), None),
            SummaryWindow::Calendar(window) => (window, None),
            SummaryWindow::PreviousFullDays(7) => ("previous7d".to_string(), None),
            SummaryWindow::PreviousFullDays(days) => (format!("previous{days}d"), None),
        };
        let time_zone = parse_reporting_tz(query.time_zone.as_deref())?.to_string();
        let upstream_account_id = match query.upstream_account_id {
            Some(account_id) if account_id > 0 => Some(account_id),
            Some(_) => return Err(anyhow!("invalid upstream account")),
            None => None,
        };

        Ok(Self {
            window,
            limit,
            time_zone,
            upstream_account_id,
        })
    }

    pub(crate) fn from_query(query: &SummaryQuery) -> Self {
        Self::try_from_query(query, 50).expect("test summary snapshot query must be valid")
    }

    fn query(&self) -> SummaryQuery {
        SummaryQuery {
            window: Some(self.window.clone()),
            limit: self.limit,
            time_zone: Some(self.time_zone.clone()),
            upstream_account_id: self.upstream_account_id,
        }
    }
}

#[derive(Debug, Clone, Default)]
pub(crate) struct SummarySnapshotEntry {
    pub(crate) response: Option<StatsResponse>,
    pub(crate) refreshed_at: Option<Instant>,
}

/// Canonical, process-local source for summary reads.  The projection intentionally stores
/// records rather than URL-keyed responses: a timezone, account, rolling window, or current-N
/// selection is a pure view over the same durable input and can therefore never borrow another
/// selection's result.
#[derive(Debug, Clone)]
pub(crate) struct SummaryProjectionRecord {
    row: UpstreamAccountInvocationPreviewRow,
    occurred_at: DateTime<Utc>,
    // Full-hour rollups cover persisted records only through their durable cursor. Archive
    // materialization has separate global and account coverage, so a global bucket never
    // suppresses an account-only fallback record.
    global_rollup_covered: bool,
    account_rollup_covered: bool,
    usage_global_rollup_covered: bool,
    usage_account_rollup_covered: bool,
    is_persisted_live_record: bool,
    // Unmaterialized archive rows are folded by the bounded account archive aggregate. Keep
    // them out of the exact-record repair pass so all-time account totals are not doubled.
    is_archive_record: bool,
    archive_has_materialized_rollups: bool,
    // When account replay is unavailable, the durable account archive aggregate already
    // contains this archive row. Keep the exact row for boundary/range views, but do not fold it
    // into the all-time account aggregate a second time.
    account_archive_totals_fallback_included: bool,
}

#[derive(Debug, Clone, Copy, Default)]
struct SummaryProjectionArchiveReplayCoverage {
    overall: bool,
    account_stats: bool,
    usage_breakdown: bool,
}

impl SummaryProjectionArchiveReplayCoverage {
    fn supports_unavailable_archive(self, archive_has_materialized_rollups: bool) -> bool {
        archive_has_materialized_rollups
            || (self.overall && self.account_stats && self.usage_breakdown)
    }
}

#[derive(Debug, Clone, Default)]
struct SummaryProjectionFreshness {
    rolling_confirmed_at: Arc<StdMutex<Option<Instant>>>,
    all_time_confirmed_at: Arc<StdMutex<Option<Instant>>>,
    all_time_account_confirmed_at: Arc<StdMutex<HashMap<i64, Instant>>>,
    global_all_time_eligible: bool,
    account_all_time_eligible: HashSet<i64>,
}

impl SummaryProjectionFreshness {
    fn rolling_at(&self, built_at: Option<Instant>) -> Option<Instant> {
        let confirmed_at = *self
            .rolling_confirmed_at
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        match (built_at, confirmed_at) {
            (Some(built_at), Some(confirmed_at)) => Some(built_at.max(confirmed_at)),
            (Some(built_at), None) => Some(built_at),
            (None, Some(confirmed_at)) => Some(confirmed_at),
            (None, None) => None,
        }
    }

    fn all_time_at(&self, built_at: Option<Instant>, account_id: Option<i64>) -> Option<Instant> {
        let confirmed_at = match account_id {
            None if self.global_all_time_eligible => *self
                .all_time_confirmed_at
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner()),
            Some(account_id) if self.account_all_time_eligible.contains(&account_id) => self
                .all_time_account_confirmed_at
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .get(&account_id)
                .copied(),
            _ => None,
        };
        match (built_at, confirmed_at) {
            (Some(built_at), Some(confirmed_at)) => Some(built_at.max(confirmed_at)),
            (Some(built_at), None) => Some(built_at),
            (None, Some(confirmed_at)) => Some(confirmed_at),
            (None, None) => None,
        }
    }

    fn confirm_unchanged(&self) {
        let now = Instant::now();
        *self
            .rolling_confirmed_at
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner()) = Some(now);
        if self.global_all_time_eligible {
            *self
                .all_time_confirmed_at
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner()) = Some(now);
        }
        if !self.account_all_time_eligible.is_empty() {
            let mut confirmed_at = self
                .all_time_account_confirmed_at
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            for account_id in &self.account_all_time_eligible {
                confirmed_at.insert(*account_id, now);
            }
        }
    }
}

#[derive(Debug, Clone, Default)]
pub(crate) struct SummaryProjection {
    records: Vec<SummaryProjectionRecord>,
    // Buckets are an index over canonical records, not a second source of truth.  They bound
    // rolling/calendar selection work without approximating a timezone boundary.
    hourly_buckets: BTreeMap<i64, Vec<usize>>,
    // Materialized history fallback.  Only compact totals remain resident; archive rows are
    // released after hydration.
    hourly_rollup_totals: HashMap<(i64, Option<i64>), StatsTotals>,
    hourly_rollup_non_success_tokens: HashMap<(i64, Option<i64>), i64>,
    // Usage rollups carry the model/reasoning dimension which is absent from StatsTotals.
    // Keep both account and global keys so a materialized archive never turns an exact
    // usage breakdown into an empty response on the memory-only request path.
    hourly_rollup_usage: HashMap<(i64, Option<i64>), UsageBreakdownResponse>,
    rollup_live_cursor: i64,
    // These indexes are constructed once off-request.  They retain only the largest legal
    // current-window result for the global view and each account, so a hot `current` read never
    // sorts or allocates in proportion to retained history.
    recent_indexes: HashMap<Option<i64>, Vec<usize>>,
    // `all` has no reporting-timezone boundary.  Hydration therefore folds the legacy
    // archive/rollup coverage rules into a canonical aggregate per account once, instead of
    // attempting to recreate those rules from raw archive rows on every request.
    all_time_by_account: HashMap<Option<i64>, StatsResponse>,
    // Regular rolling refreshes may reuse all-time responses when no all-time owner is active;
    // keep their freshness independent from the projection-wide timestamp.
    all_time_refreshed_at: Option<Instant>,
    // Global all-time rollups and account archive fallbacks have independent durable coverage.
    // A failed account rebuild must not make a fresh global aggregate stale, and an old account
    // response must never borrow the global aggregate's freshness.
    all_time_account_refreshed_at: HashMap<i64, Instant>,
    // Archive files are immutable once completed. Reuse their bounded account-key discovery on
    // later refreshes so maintenance never repeatedly scans a large low-cardinality archive.
    archive_account_ids_by_file: HashMap<String, HashSet<i64>>,
    // An unreadable unmaterialized archive has no exact in-memory source. Keep its bounded
    // overlap range so rolling/calendar requests fail closed instead of silently undercounting.
    // Materialized archives are intentionally excluded: their durable rollups remain a valid
    // source even when the raw file is unavailable.
    unavailable_unmaterialized_archive_ranges: Vec<ExactUtcRange>,
    // Closed calendar windows are immutable at a projection revision. Only the small global
    // bootstrap set is pre-rendered; account-scoped selections remain pure views over canonical
    // buckets so account count cannot multiply refresh allocations.
    closed_window_by_key: HashMap<SummarySnapshotKey, StatsResponse>,
    // In-progress state is not the same thing as a row whose persisted status happens to be
    // `running`: the typed runtime overlay reconciles terminal replacements and retry lineage.
    // Keep that reconciled view alongside the immutable history projection.
    in_progress_by_account: HashMap<Option<i64>, InProgressSummarySnapshot>,
    maintenance: Option<StatsMaintenanceResponse>,
    refreshed_at: Option<Instant>,
    freshness: SummaryProjectionFreshness,
    revision: u64,
}

impl SummaryProjection {
    fn response_for_query(
        &self,
        params: &SummaryQuery,
        default_limit: i64,
    ) -> Result<StatsResponse, ApiError> {
        validate_summary_projection_window(params, default_limit)?;
        let rolling_refreshed_at = self.freshness.rolling_at(self.refreshed_at);
        let last_good_age_ms =
            rolling_refreshed_at.map(|refreshed_at| refreshed_at.elapsed().as_millis() as u64);
        debug!(
            ?last_good_age_ms,
            revision = self.revision,
            "serving summary projection from memory"
        );

        let window = parse_summary_window(params, default_limit)?;
        let reporting_tz = parse_reporting_tz(params.time_zone.as_deref())?;
        let upstream_account_id = match params.upstream_account_id {
            Some(account_id) if account_id > 0 => Some(account_id),
            Some(_) => return Err(ApiError::bad_request(anyhow!("invalid upstream account"))),
            None => None,
        };
        let key = SummarySnapshotKey::try_from_query(params, default_limit)
            .map_err(ApiError::bad_request)?;
        let now = Utc::now();
        let range = summary_window_range(&window, reporting_tz, now)?;
        if let Some((start, end)) = range
            && self
                .unavailable_unmaterialized_archive_ranges
                .iter()
                .any(|unavailable| unavailable.start < end && start < unavailable.end)
        {
            return Err(ApiError::unavailable(anyhow!(
                "summary projection archive source is unavailable for the requested range"
            )));
        }
        if self
            .freshness
            .rolling_at(self.refreshed_at)
            .is_none_or(|refreshed_at| refreshed_at.elapsed() > SUMMARY_SNAPSHOT_MAX_STALE)
        {
            return Err(ApiError::unavailable(anyhow!(
                "summary projection last-good snapshot exceeded the freshness budget"
            )));
        }
        if let Some(response) = self.closed_window_by_key.get(&key) {
            return Ok(response.clone());
        }
        if matches!(window, SummaryWindow::All) {
            let all_time_refreshed_at = self.freshness.all_time_at(
                match upstream_account_id {
                    None => self.all_time_refreshed_at,
                    Some(account_id) => {
                        self.all_time_account_refreshed_at.get(&account_id).copied()
                    }
                },
                upstream_account_id,
            );
            if all_time_refreshed_at
                .is_none_or(|refreshed_at| refreshed_at.elapsed() > SUMMARY_SNAPSHOT_MAX_STALE)
            {
                return Err(ApiError::unavailable(anyhow!(
                    "summary all-time last-good snapshot exceeded the freshness budget"
                )));
            }
            if let Some(response) = self.all_time_by_account.get(&upstream_account_id) {
                return Ok(response.clone());
            }
            if upstream_account_id.is_some() {
                return Err(ApiError::unavailable(anyhow!(
                    "summary all-time account snapshot is not hydrated"
                )));
            }
        }
        let candidate_indexes = range.map_or_else(
            || {
                if let SummaryWindow::Current(_) = window {
                    return self
                        .recent_indexes
                        .get(&upstream_account_id)
                        .cloned()
                        .unwrap_or_default();
                }
                (0..self.records.len()).collect::<Vec<_>>()
            },
            |(start, end)| {
                let first_bucket = align_bucket_epoch(start.timestamp(), 3_600, 0);
                let last_bucket = align_bucket_epoch(end.timestamp(), 3_600, 0);
                self.hourly_buckets
                    .range(first_bucket..=last_bucket)
                    .flat_map(|(_, indexes)| indexes.iter().copied())
                    .collect()
            },
        );
        let full_rollup_range = range.and_then(|(start, end)| {
            let first_full_hour = ceil_hour_epoch(start.timestamp());
            let end_full_hour = align_bucket_epoch(end.timestamp(), 3_600, 0);
            (first_full_hour < end_full_hour).then_some((first_full_hour, end_full_hour))
        });
        let is_full_rollup_bucket = |record: &SummaryProjectionRecord| {
            full_rollup_range.is_some_and(|(start, end)| {
                let bucket = align_bucket_epoch(record.occurred_at.timestamp(), 3_600, 0);
                bucket >= start && bucket < end
            })
        };
        let mut selected = candidate_indexes
            .iter()
            .copied()
            .map(|index| &self.records[index])
            .filter(|record| {
                upstream_account_id
                    .is_none_or(|account_id| record.row.upstream_account_id == Some(account_id))
            })
            .filter(|record| {
                range.is_none_or(|(start, end)| {
                    record.occurred_at >= start && record.occurred_at < end
                })
            })
            .filter(|record| {
                if !is_full_rollup_bucket(record) {
                    return true;
                }
                if record.is_persisted_live_record {
                    let scope_covered = match upstream_account_id {
                        None => record.global_rollup_covered,
                        Some(_) => record.account_rollup_covered,
                    };
                    if !scope_covered {
                        return true;
                    }
                }
                match upstream_account_id {
                    None => !record.global_rollup_covered,
                    Some(_) => !record.account_rollup_covered,
                }
            })
            .collect::<Vec<_>>();
        let mut usage_selected = candidate_indexes
            .iter()
            .copied()
            .map(|index| &self.records[index])
            .filter(|record| {
                upstream_account_id
                    .is_none_or(|account_id| record.row.upstream_account_id == Some(account_id))
            })
            .filter(|record| {
                range.is_none_or(|(start, end)| {
                    record.occurred_at >= start && record.occurred_at < end
                })
            })
            .filter(|record| {
                if !is_full_rollup_bucket(record) {
                    return true;
                }
                if record.is_persisted_live_record {
                    let scope_covered = match upstream_account_id {
                        None => record.usage_global_rollup_covered,
                        Some(_) => record.usage_account_rollup_covered,
                    };
                    if !scope_covered {
                        return true;
                    }
                }
                let bucket = align_bucket_epoch(record.occurred_at.timestamp(), 3_600, 0);
                let usage_rollup_covered = match upstream_account_id {
                    None => record.usage_global_rollup_covered,
                    Some(_) => record.usage_account_rollup_covered,
                } && self
                    .hourly_rollup_usage
                    .contains_key(&(bucket, upstream_account_id));
                !usage_rollup_covered
            })
            .collect::<Vec<_>>();

        if let SummaryWindow::Current(limit) = window {
            let limit = limit.max(0) as usize;
            selected.truncate(limit);
            usage_selected.truncate(limit);
        }

        let mut totals = StatsTotals::default();
        let mut usage_breakdown = UsageBreakdownAccumulator::default();
        let mut non_success_tokens = 0_i64;

        for record in &selected {
            let row = &record.row;
            let classification = resolve_failure_classification(
                Some(row.status.as_str()),
                row.error_message.as_deref(),
                row.failure_kind.as_deref(),
                row.failure_class.as_deref(),
                row.is_actionable,
            );
            let status = normalized_runtime_text(Some(row.status.as_str()));
            let terminal = !matches!(status.as_str(), "running" | "pending");
            let success = runtime_record_is_success_for_summary_row(row)
                && classification.failure_class == FailureClass::None;
            let failure = terminal && classification.failure_class != FailureClass::None;

            totals.total_count += 1;
            totals.total_cost += row.cost.unwrap_or_default();
            totals.total_tokens += row.total_tokens;
            if success {
                totals.success_count += 1;
            }
            if failure {
                totals.failure_count += 1;
                totals.non_success_cost += row.cost.unwrap_or_default();
                non_success_tokens += row.total_tokens.max(0);
            }
        }
        for record in &usage_selected {
            usage_breakdown.add_row(&record.row);
        }

        if let Some((start, end)) = full_rollup_range {
            for ((bucket, account), bucket_totals) in &self.hourly_rollup_totals {
                if *bucket < start || *bucket >= end {
                    continue;
                }
                if *account != upstream_account_id {
                    continue;
                }
                totals = totals.add(*bucket_totals);
                non_success_tokens += self
                    .hourly_rollup_non_success_tokens
                    .get(&(*bucket, *account))
                    .copied()
                    .unwrap_or_default();
            }
            for ((bucket, account), usage) in &self.hourly_rollup_usage {
                if *bucket >= start && *bucket < end && *account == upstream_account_id {
                    usage_breakdown.merge_response(usage);
                }
            }
        }

        let mut response = totals.into_response();
        response.non_success_cost = Some(totals.non_success_cost);
        if range.is_some() {
            response.usage_breakdown = Some(usage_breakdown.into_response());
        }

        let policy = summary_live_augmentation_policy(&window, range, now);
        if policy.include_in_progress {
            let in_progress = self
                .in_progress_by_account
                .get(&upstream_account_id)
                .copied()
                .unwrap_or_default();
            response.in_progress_conversation_count = Some(in_progress.in_progress_count);
            response.in_progress_retry_conversation_count = Some(in_progress.retry_count);
            response.in_progress_avg_wait_ms = in_progress.avg_wait_ms;
            response.in_progress_phase_counts = Some(in_progress.phase_counts);
        }
        if policy.include_non_success_tokens {
            response.non_success_tokens = Some(non_success_tokens);
        }
        response.maintenance = self.maintenance.clone();
        Ok(response)
    }
}

fn runtime_record_is_success_for_summary_row(row: &UpstreamAccountInvocationPreviewRow) -> bool {
    let status = normalized_runtime_text(Some(row.status.as_str()));
    matches!(
        status.as_str(),
        "success" | "completed" | INVOCATION_STATUS_WARNING_SUCCESS
    ) || (status == "http_200" && normalized_runtime_text(row.error_message.as_deref()).is_empty())
}

fn summary_projection_record_totals(record: &SummaryProjectionRecord) -> StatsTotals {
    let classification = resolve_failure_classification(
        Some(record.row.status.as_str()),
        record.row.error_message.as_deref(),
        record.row.failure_kind.as_deref(),
        record.row.failure_class.as_deref(),
        record.row.is_actionable,
    );
    let status = normalized_runtime_text(Some(record.row.status.as_str()));
    let terminal = !matches!(status.as_str(), "running" | "pending");
    let mut totals = StatsTotals {
        total_count: 1,
        total_tokens: record.row.total_tokens,
        total_cost: record.row.cost.unwrap_or_default(),
        ..StatsTotals::default()
    };
    if runtime_record_is_success_for_summary_row(&record.row)
        && classification.failure_class == FailureClass::None
    {
        totals.success_count = 1;
    }
    if terminal && classification.failure_class != FailureClass::None {
        totals.failure_count = 1;
        totals.non_success_cost = record.row.cost.unwrap_or_default();
    }
    totals
}

fn summary_projection_account_record_totals(
    record: &SummaryProjectionRecord,
) -> Option<(i64, StatsTotals)> {
    let account_id = record.row.upstream_account_id.filter(|id| *id > 0)?;
    if record.account_rollup_covered
        || record.account_archive_totals_fallback_included
        // Unmaterialized archive totals are loaded once by the bounded account aggregate below;
        // retaining the exact row for rolling/usage views must not add it to all-time a second time.
        || (record.is_archive_record && !record.archive_has_materialized_rollups)
    {
        return None;
    }
    Some((account_id, summary_projection_record_totals(record)))
}

fn summary_projection_optional_string_bytes(value: Option<&String>) -> usize {
    value.map_or(0, String::len)
}

fn summary_projection_preview_row_bytes(row: &UpstreamAccountInvocationPreviewRow) -> usize {
    row.invoke_id.len()
        + row.occurred_at.len()
        + row.status.len()
        + summary_projection_optional_string_bytes(row.prompt_cache_key.as_ref())
        + summary_projection_optional_string_bytes(row.conversation_created_at.as_ref())
        + summary_projection_optional_string_bytes(row.live_phase.as_ref())
        + summary_projection_optional_string_bytes(row.failure_class.as_ref())
        + summary_projection_optional_string_bytes(row.route_mode.as_ref())
        + summary_projection_optional_string_bytes(row.model.as_ref())
        + summary_projection_optional_string_bytes(row.request_model.as_ref())
        + summary_projection_optional_string_bytes(row.response_model.as_ref())
        + summary_projection_optional_string_bytes(row.reasoning_effort.as_ref())
        + summary_projection_optional_string_bytes(row.source.as_ref())
        + summary_projection_optional_string_bytes(row.error_message.as_ref())
        + summary_projection_optional_string_bytes(row.downstream_error_message.as_ref())
        + summary_projection_optional_string_bytes(row.failure_kind.as_ref())
        + summary_projection_optional_string_bytes(row.proxy_display_name.as_ref())
        + summary_projection_optional_string_bytes(row.upstream_account_name.as_ref())
        + summary_projection_optional_string_bytes(row.upstream_account_plan_type.as_ref())
        + summary_projection_optional_string_bytes(row.response_content_encoding.as_ref())
        + summary_projection_optional_string_bytes(row.request_compression_algorithm.as_ref())
        + summary_projection_optional_string_bytes(row.transport.as_ref())
        + summary_projection_optional_string_bytes(row.requested_service_tier.as_ref())
        + summary_projection_optional_string_bytes(row.service_tier.as_ref())
        + summary_projection_optional_string_bytes(row.billing_service_tier.as_ref())
        + summary_projection_optional_string_bytes(row.endpoint.as_ref())
        + summary_projection_optional_string_bytes(row.compaction_request_kind.as_ref())
        + summary_projection_optional_string_bytes(row.compaction_response_kind.as_ref())
        + summary_projection_optional_string_bytes(row.image_intent.as_ref())
}

fn summary_projection_archive_row_bytes(row: &SummaryProjectionArchiveRow) -> usize {
    row.invoke_id.len()
        + row.occurred_at.len()
        + row.source.len()
        + summary_projection_optional_string_bytes(row.model.as_ref())
        + summary_projection_optional_string_bytes(row.response_model.as_ref())
        + summary_projection_optional_string_bytes(row.reasoning_effort.as_ref())
        + row.status.len()
        + summary_projection_optional_string_bytes(row.error_message.as_ref())
        + summary_projection_optional_string_bytes(row.failure_kind.as_ref())
        + summary_projection_optional_string_bytes(row.failure_class.as_ref())
}

